// Not a literal translation: what the śloka is saying, in plain words (English, Telugu, Hindi). Key = vsn_<section>_<n>.
window.SIMPLE = Object.assign(window.SIMPLE || {}, {
"vsn_preamble_1": {"en":"Before starting anything important, we picture God calm, bright and smiling. White stands for purity, the moonlight for coolness and peace, and the four arms for His power to protect us from every side. Starting with a peaceful mind like this helps us face whatever comes, and that is how the obstacles go away.","te":"ఏ ముఖ్యమైన పని మొదలుపెట్టే ముందైనా ప్రశాంతంగా, ప్రకాశంగా, నవ్వుతూ ఉన్న దేవుణ్ణి మనసులో తలచుకుంటాం. తెలుపు స్వచ్ఛతకు, వెన్నెల చల్లదనానికీ శాంతికీ, నాలుగు భుజాలు అన్ని వైపుల నుండీ కాపాడే శక్తికీ గుర్తు. ఇలా ప్రశాంతమైన మనసుతో మొదలుపెడితే ఏది వచ్చినా ఎదుర్కోగలం — అలా విఘ్నాలు తొలగిపోతాయి.","hi":"कोई भी महत्वपूर्ण काम शुरू करने से पहले हम भगवान को शांत, उज्ज्वल और मुस्कुराते हुए मन में लाते हैं। सफ़ेद रंग पवित्रता का, चाँदनी शीतलता और शांति का, और चार भुजाएँ हर ओर से रक्षा करने की शक्ति का प्रतीक हैं। ऐसे शांत मन से शुरू करें तो जो भी आए उसका सामना कर सकते हैं — ऐसे ही विघ्न दूर होते हैं।"},
"vsn_preamble_2": {"en":"Viṣvaksena is the commander of Viṣṇu's attendants, the one who clears the way. We bow to him first so that our recitation goes smoothly — just as we greet the gatekeeper respectfully before entering a king's palace.","te":"విష్వక్సేనుడు విష్ణువు పరివారానికి సేనాధిపతి — దారిని సిద్ధం చేసేవాడు. మన పారాయణం సజావుగా సాగాలని ముందుగా ఆయనకు నమస్కరిస్తాం — రాజభవనంలోకి వెళ్ళే ముందు ద్వారపాలకుణ్ణి గౌరవంగా పలకరించినట్టు.","hi":"विष्वक्सेन विष्णु के पार्षदों के सेनापति हैं — जो मार्ग साफ़ करते हैं। पाठ निर्विघ्न हो, इसलिए पहले उन्हें प्रणाम करते हैं — जैसे राजमहल में जाने से पहले द्वारपाल का आदर से अभिवादन करते हैं।"},
"vsn_purva_3": {"en":"Before any hymn, we remember the teacher who gave it to us. Vyāsa, who compiled the Vedas and wrote the Mahābhārata, comes from a great family of sages. Remembering him is like thanking the one who carried this treasure down to us.","te":"ఏ స్తోత్రమైనా పఠించే ముందు దాన్ని మనకు అందించిన గురువును స్మరిస్తాం. వేదాలను విభజించి, మహాభారతాన్ని రచించిన వ్యాసుడు గొప్ప ఋషి వంశానికి చెందినవాడు. ఆయనను తలచుకోవడం ఈ నిధిని మనవరకు తెచ్చినవారికి కృతజ్ఞత చెప్పడమే.","hi":"किसी भी स्तोत्र से पहले उसे देने वाले गुरु का स्मरण करते हैं। वेदों का विभाग करने वाले और महाभारत लिखने वाले व्यास महान ऋषि-कुल से हैं। उन्हें याद करना इस ख़ज़ाने को हम तक लाने वाले को धन्यवाद देना है।"},
"vsn_purva_4": {"en":"The tradition sees Vyāsa and Viṣṇu as one: God Himself came as Vyāsa to give us the scriptures. So honouring the teacher and honouring God are the same act.","te":"వ్యాసుడూ విష్ణువూ ఒక్కరే అని సంప్రదాయం భావిస్తుంది: మనకు శాస్త్రాలను ఇవ్వడానికి దేవుడే వ్యాసునిగా వచ్చాడు. కాబట్టి గురువును గౌరవించడం, దేవుణ్ణి గౌరవించడం ఒకటే.","hi":"परंपरा व्यास और विष्णु को एक मानती है: शास्त्र देने के लिए स्वयं भगवान व्यास बनकर आए। इसलिए गुरु का सम्मान और भगवान का सम्मान एक ही बात है।"},
"vsn_purva_5": {"en":"Everything around us changes — our bodies, moods, the world. Viṣṇu is the one thing that never changes, always pure and the same. Bowing to Him reminds us there is something steady to hold on to.","te":"మన చుట్టూ ఉన్నదంతా మారుతూనే ఉంటుంది — శరీరం, మనసు, ప్రపంచం. ఎప్పుడూ మారకుండా, ఎల్లప్పుడూ పవిత్రంగా, ఒకేలా ఉండేది విష్ణువు ఒక్కడే. ఆయనకు నమస్కరిస్తే పట్టుకోవడానికి ఒక స్థిరమైన ఆధారం ఉందని గుర్తొస్తుంది.","hi":"हमारे आसपास सब बदलता है — शरीर, मन, संसार। विष्णु ही वे हैं जो कभी नहीं बदलते, सदा पवित्र और एक-से। उन्हें नमन करना याद दिलाता है कि पकड़ने के लिए कुछ स्थिर है।"},
"vsn_purva_6": {"en":"You don't need long rituals — just remembering Him with love is enough to loosen the knots that bind us to worry and rebirth. That is the promise behind chanting His names.","te":"పెద్ద పెద్ద కర్మలు అవసరం లేదు — ప్రేమతో ఆయనను స్మరించడమే చాలు; మనల్ని ఆందోళనకూ పునర్జన్మకూ కట్టిపడేసే ముడులు సడలిపోతాయి. ఆయన నామాలు జపించడం వెనుక ఉన్న వాగ్దానం ఇదే.","hi":"लंबे अनुष्ठानों की ज़रूरत नहीं — प्रेम से उन्हें याद करना ही चिंता और पुनर्जन्म की गाँठें खोलने के लिए काफ़ी है। उनके नाम जपने के पीछे यही वचन है।"},
"vsn_purva_7": {"en":"The setting: the Mahābhārata war is over, and Bhīṣma lies on his bed of arrows, teaching Yudhiṣṭhira. After hearing about every kind of dharma, Yudhiṣṭhira still has one deep question left.","te":"నేపథ్యం: మహాభారత యుద్ధం ముగిసింది; అంపశయ్యపై ఉన్న భీష్ముడు ధర్మరాజుకు బోధిస్తున్నాడు. అన్ని రకాల ధర్మాలూ విన్న తర్వాత కూడా ధర్మరాజుకు ఒక లోతైన ప్రశ్న మిగిలి ఉంది.","hi":"पृष्ठभूमि: महाभारत युद्ध समाप्त हो चुका है और भीष्म बाणों की शय्या पर युधिष्ठिर को उपदेश दे रहे हैं। हर तरह के धर्म सुनने के बाद भी युधिष्ठिर का एक गहरा प्रश्न बाकी है।"},
"vsn_purva_8": {"en":"Yudhiṣṭhira asks what everyone wonders: of all the gods and paths, which one is the true God, the final shelter? Whom should I praise and worship to find real good in life?","te":"అందరికీ కలిగే సందేహాన్నే ధర్మరాజు అడుగుతున్నాడు: ఇన్ని దేవతలు, ఇన్ని మార్గాలలో నిజమైన దైవం ఎవరు, చివరి ఆశ్రయం ఏది? జీవితంలో నిజమైన మేలు పొందడానికి ఎవరిని స్తుతించాలి, ఎవరిని పూజించాలి?","hi":"युधिष्ठिर वही पूछते हैं जो सबके मन में है: इतने देवताओं और मार्गों में सच्चा भगवान कौन है, अंतिम आश्रय क्या है? जीवन में सच्चा भला पाने के लिए किसकी स्तुति और पूजा करूँ?"},
"vsn_purva_9": {"en":"He also asks: what is the highest dharma of all, and what can a person chant to be truly free? These six questions are why the Sahasranāma was given.","te":"ఇంకా అడుగుతున్నాడు: అన్నిటిలో ఉత్తమమైన ధర్మం ఏది? దేనిని జపిస్తే మనిషి నిజంగా విముక్తుడవుతాడు? ఈ ఆరు ప్రశ్నలకు జవాబుగానే సహస్రనామం వచ్చింది.","hi":"वे यह भी पूछते हैं: सबसे श्रेष्ठ धर्म कौन-सा है, और क्या जपने से मनुष्य सच में मुक्त होता है? इन्हीं छह प्रश्नों के उत्तर में सहस्रनाम दिया गया।"},
"vsn_purva_10": {"en":"Bhīṣma begins his answer: the person who stays alert and keeps praising the Lord of the world through these thousand names —","te":"భీష్ముడు జవాబు మొదలుపెడుతున్నాడు: జాగ్రత్తగా, ఉత్సాహంగా ఉంటూ ఈ వేయి నామాలతో జగత్ప్రభువును నిరంతరం స్తుతించేవాడు —","hi":"भीष्म उत्तर शुरू करते हैं: जो सजग रहकर इन सहस्र नामों से जगत के प्रभु की निरंतर स्तुति करता है —"},
"vsn_purva_11": {"en":"— who worships Him daily with love, thinks of Him, praises Him and bows to Him. Notice it's the whole person: thought, words and actions all turned towards God.","te":"— ప్రతిరోజూ ప్రేమతో ఆయనను పూజిస్తూ, తలచుకుంటూ, స్తుతిస్తూ, నమస్కరించేవాడు. గమనించండి — ఆలోచన, మాట, పని అన్నీ దేవుని వైపే మళ్ళాయి.","hi":"— जो प्रतिदिन प्रेम से उनकी पूजा, स्मरण, स्तुति और नमस्कार करता है। ध्यान दें — विचार, वाणी और कर्म सब भगवान की ओर।"},
"vsn_purva_12": {"en":"— such a person rises above all sorrow. That is the answer to 'how do I become free?': keep praising the One who has no beginning or end.","te":"— అలాంటి మనిషి అన్ని దుఃఖాలనూ దాటిపోతాడు. ‘నేను ఎలా విముక్తుడవుతాను?’ అనే ప్రశ్నకు జవాబు ఇదే: ఆది అంతం లేనివానిని స్తుతిస్తూ ఉండడం.","hi":"— ऐसा व्यक्ति सब दुःखों से ऊपर उठ जाता है। 'मैं कैसे मुक्त होऊँ?' का यही उत्तर है: आदि-अंत रहित की स्तुति करते रहो।"},
"vsn_purva_13": {"en":"Bhīṣma describes who this God is: He loves goodness and knowledge, knows what is right, makes the world flourish, and is the very source of every living being.","te":"ఈ దేవుడు ఎవరో భీష్ముడు వివరిస్తున్నాడు: ఆయన మంచితనాన్నీ జ్ఞానాన్నీ ప్రేమిస్తాడు, ఏది సరైనదో తెలిసినవాడు, లోకాన్ని వర్ధిల్లజేస్తాడు, ప్రతి ప్రాణికీ మూలం ఆయనే.","hi":"भीष्म बताते हैं कि यह भगवान कौन हैं: वे भलाई और ज्ञान से प्रेम करते हैं, सही-गलत जानते हैं, संसार को फलने-फूलने देते हैं और हर प्राणी के मूल हैं।"},
"vsn_purva_14": {"en":"Bhīṣma's personal conclusion after a whole lifetime: the best dharma of all is simply to worship God with love and praise. Not complicated — just sincere.","te":"జీవితమంతా గడిపిన తర్వాత భీష్ముని సొంత నిర్ణయం: అన్నిటికంటే ఉత్తమ ధర్మం ప్రేమతో, స్తోత్రాలతో దేవుణ్ణి పూజించడమే. క్లిష్టమైనది కాదు — కేవలం నిజాయితీ కావాలి.","hi":"पूरा जीवन बिताने के बाद भीष्म का अपना निष्कर्ष: सबसे श्रेष्ठ धर्म है प्रेम और स्तुति से भगवान की पूजा। जटिल नहीं — बस सच्चा होना चाहिए।"},
"vsn_purva_15": {"en":"Whatever is greatest — the greatest light, the greatest effort, the greatest truth, the greatest shelter — that is Him. Everything great we know is only a small reflection of Him.","te":"అన్నిటికంటే గొప్పదేదైనా — గొప్ప వెలుగు, గొప్ప తపస్సు, గొప్ప సత్యం, గొప్ప ఆశ్రయం — అది ఆయనే. మనకు తెలిసిన గొప్పదంతా ఆయన చిన్న ప్రతిబింబం మాత్రమే.","hi":"जो भी सबसे बड़ा है — सबसे बड़ा प्रकाश, सबसे बड़ा तप, सबसे बड़ा सत्य, सबसे बड़ा आश्रय — वही हैं। हमें ज्ञात हर महान चीज़ उनका छोटा-सा प्रतिबिंब है।"},
"vsn_purva_16": {"en":"Holy rivers and temples make us pure, but He is what makes them holy. Good things bring blessings, but He is the source of all blessing. And He is the Father who never dies.","te":"పుణ్య నదులూ ఆలయాలూ మనల్ని పవిత్రం చేస్తాయి, కానీ వాటిని పవిత్రం చేసేది ఆయనే. మంచివన్నీ శుభం ఇస్తాయి, కానీ శుభానికి మూలం ఆయనే. ఆయన ఎన్నటికీ మరణించని తండ్రి.","hi":"पवित्र नदियाँ और मंदिर हमें पवित्र करते हैं, पर उन्हें पवित्र करने वाले वही हैं। अच्छी चीज़ें मंगल देती हैं, पर मंगल का स्रोत वही हैं। और वे कभी न मरने वाले पिता हैं।"},
"vsn_purva_17": {"en":"Like waves rising from the ocean and falling back into it, the whole universe comes from Him at the start of time and returns to Him at the end.","te":"సముద్రం నుండి అలలు లేచి మళ్ళీ అందులోనే కలిసినట్టు, కాలారంభంలో విశ్వమంతా ఆయన నుండే పుట్టి, అంతంలో మళ్ళీ ఆయనలోనే కలుస్తుంది.","hi":"जैसे लहरें समुद्र से उठकर उसी में लौट जाती हैं, वैसे ही सारा विश्व समय के आरंभ में उन्हीं से निकलता है और अंत में उन्हीं में लौटता है।"},
"vsn_purva_18": {"en":"Now Bhīṣma invites Yudhiṣṭhira — and us — to listen: here come the thousand names, which take away both our wrongdoings and our fears.","te":"ఇప్పుడు భీష్ముడు ధర్మరాజునూ — మనల్నీ — వినమని ఆహ్వానిస్తున్నాడు: మన తప్పులనూ భయాలనూ పోగొట్టే వేయి నామాలు ఇవిగో.","hi":"अब भीष्म युधिष्ठिर को — और हमें — सुनने का निमंत्रण देते हैं: ये रहे सहस्र नाम, जो हमारे पाप और भय दोनों दूर करते हैं।"},
"vsn_purva_19": {"en":"These names aren't random — each one describes a real quality of God, and they were sung by the great sages. Each name is a small window into who He is.","te":"ఈ నామాలు ఊరికే పెట్టినవి కావు — ప్రతి నామమూ దేవుని నిజమైన గుణాన్ని వర్ణిస్తుంది; మహర్షులు వాటిని గానం చేశారు. ప్రతి నామమూ ఆయన ఎవరో చూపించే చిన్న కిటికీ.","hi":"ये नाम यूँ ही नहीं — हर नाम भगवान के किसी सच्चे गुण का वर्णन है, और महर्षियों ने इन्हें गाया है। हर नाम उन्हें जानने की एक छोटी खिड़की है।"},
"vsn_purva_20": {"en":"Every Vedic hymn has a 'label': who first saw it (the ṛṣi), its rhythm (the metre) and to whom it is addressed (the deity). Here: seer Vyāsa, metre anuṣṭubh, deity Kṛṣṇa.","te":"ప్రతి వైదిక స్తోత్రానికీ ఒక ‘గుర్తింపు’ ఉంటుంది: దాన్ని మొదట దర్శించినవారు (ఋషి), దాని లయ (ఛందస్సు), ఎవరిని ఉద్దేశించినది (దేవత). ఇక్కడ: ఋషి వ్యాసుడు, ఛందస్సు అనుష్టుప్, దేవత శ్రీకృష్ణుడు.","hi":"हर वैदिक स्तोत्र की एक 'पहचान' होती है: पहले किसने देखा (ऋषि), उसकी लय (छंद) और किसे संबोधित (देवता)। यहाँ: ऋषि व्यास, छंद अनुष्टुप्, देवता श्रीकृष्ण।"},
"vsn_purva_21": {"en":"Like a seed, a power and a heart give life to a plant, certain key names give this hymn its power. It's recited mainly for peace — inner and outer.","te":"బీజం, శక్తి, హృదయం ఒక మొక్కకు ప్రాణం పోసినట్టు, కొన్ని ముఖ్యమైన నామాలు ఈ స్తోత్రానికి శక్తినిస్తాయి. దీనిని ముఖ్యంగా శాంతి కోసం — లోపలా బయటా — పఠిస్తారు.","hi":"जैसे बीज, शक्ति और हृदय एक पौधे को जीवन देते हैं, वैसे ही कुछ मुख्य नाम इस स्तोत्र को शक्ति देते हैं। इसका पाठ मुख्यतः शांति के लिए — भीतर और बाहर — किया जाता है।"},
"vsn_purva_22": {"en":"A final salute before the names begin: to the all-pervading, ever-victorious Lord who takes many forms to protect the world. We start the recitation with our heads bowed.","te":"నామాలు మొదలయ్యే ముందు చివరి నమస్కారం: అంతటా వ్యాపించి, ఎప్పుడూ జయించే, లోకాన్ని రక్షించడానికి అనేక రూపాలు ధరించే ప్రభువుకు. తల వంచి పారాయణం మొదలుపెడతాం.","hi":"नाम शुरू होने से पहले अंतिम प्रणाम: सर्वव्यापी, सदा विजयी प्रभु को, जो जगत की रक्षा के लिए अनेक रूप लेते हैं। सिर झुकाकर हम पाठ आरंभ करते हैं।"},
"vsn_dhyanam_1": {"en":"Before chanting, we paint a picture in our mind: Viṣṇu sitting peacefully on a pearl seat by the milk ocean, cool clouds raining nectar above. Holding this calm, beautiful image helps the mind settle before the names begin.","te":"జపించే ముందు మనసులో ఒక చిత్రం గీసుకుంటాం: పాలసముద్ర తీరంలో ముత్యాల ఆసనంపై ప్రశాంతంగా కూర్చున్న విష్ణువు, పైన అమృతం కురిపించే చల్లని మేఘాలు. ఈ ప్రశాంతమైన, అందమైన దృశ్యాన్ని నిలుపుకుంటే నామాలు మొదలయ్యే ముందు మనసు కుదురుకుంటుంది.","hi":"जपने से पहले हम मन में एक चित्र बनाते हैं: क्षीर-सागर के तट पर मोतियों के आसन पर शांति से बैठे विष्णु, ऊपर अमृत बरसाते शीतल बादल। यह शांत, सुंदर छवि मन को नाम शुरू होने से पहले स्थिर करती है।"},
"vsn_dhyanam_2": {"en":"Now imagine the whole universe as God's body: the earth His feet, the sky His navel, the sun and moon His eyes. Everything we see — every person, animal and star — lives inside Him. God is not far away; we are within Him.","te":"ఇప్పుడు విశ్వమంతా దేవుని శరీరంగా ఊహించండి: భూమి ఆయన పాదాలు, ఆకాశం నాభి, సూర్యచంద్రులు కన్నులు. మనం చూసే ప్రతిదీ — ప్రతి మనిషి, జంతువు, నక్షత్రం — ఆయనలోనే ఉంది. దేవుడు దూరంగా లేడు; మనమే ఆయనలో ఉన్నాం.","hi":"अब पूरे विश्व को भगवान का शरीर मानो: पृथ्वी उनके चरण, आकाश नाभि, सूर्य-चंद्र नेत्र। जो कुछ हम देखते हैं — हर व्यक्ति, जीव और तारा — उन्हीं के भीतर है। भगवान दूर नहीं; हम उनके भीतर हैं।"},
"vsn_dhyanam_3": {"en":"One of the best-loved verses: God peaceful as He rests on the serpent, vast as the sky, dark as a rain cloud, the one yogīs find in their hearts. Remembering Him this way melts away the fear that life brings.","te":"అత్యంత ప్రియమైన శ్లోకాలలో ఒకటి: శేషునిపై ప్రశాంతంగా శయనించిన, ఆకాశమంత విశాలమైన, వర్షమేఘం వలె నల్లని, యోగులు హృదయంలో దర్శించే దేవుడు. ఆయనను ఇలా తలచుకుంటే జీవితంలోని భయం కరిగిపోతుంది.","hi":"सबसे प्रिय श्लोकों में एक: शेषनाग पर शांति से विश्राम करते, आकाश जैसे विशाल, वर्षा-मेघ जैसे श्याम, योगियों को हृदय में मिलने वाले भगवान। उन्हें ऐसे याद करने से जीवन का भय पिघल जाता है।"},
"vsn_dhyanam_4": {"en":"Another picture to hold: dark like a cloud, in shining yellow silk, the Kaustubha jewel glowing on His chest, eyes like lotus petals. Simple, beautiful images like these make prayer feel personal.","te":"నిలుపుకోవలసిన మరో చిత్రం: మేఘం వలె నల్లని శరీరం, మెరిసే పసుపు పట్టు, వక్షస్థలంపై వెలిగే కౌస్తుభం, తామర రేకుల వంటి కన్నులు. ఇలాంటి సరళమైన, అందమైన దృశ్యాలు ప్రార్థనను మనకు దగ్గరగా చేస్తాయి.","hi":"एक और छवि: बादल जैसे श्याम, चमकते पीले रेशम में, वक्ष पर दमकता कौस्तुभ, कमल-दल जैसे नेत्र। ऐसी सरल, सुंदर छवियाँ प्रार्थना को अपनापन देती हैं।"},
"vsn_dhyanam_5": {"en":"A short salute: God was there before everything, holds up the world, and appears in countless forms. Whatever form we love Him in, it is still Him.","te":"ఒక చిన్న నమస్కారం: అన్నిటికంటే ముందు దేవుడే ఉన్నాడు, లోకాన్ని ఆయనే ధరిస్తున్నాడు, అనేక రూపాలలో కనిపిస్తాడు. ఏ రూపంలో ఆయనను ప్రేమించినా, అది ఆయనే.","hi":"एक छोटा प्रणाम: सबसे पहले भगवान ही थे, वही संसार को थामे हैं, और अनगिनत रूपों में दिखते हैं। किसी भी रूप में उनसे प्रेम करें, वह वही हैं।"},
"vsn_dhyanam_6": {"en":"A full picture of Viṣṇu from head to toe — crown, earrings, conch, discus, yellow robes, lotus eyes, four arms. We bow our heads to Him, as a child bows to a loving parent.","te":"తల నుండి పాదాల వరకు విష్ణువు సంపూర్ణ చిత్రం — కిరీటం, కుండలాలు, శంఖం, చక్రం, పసుపు వస్త్రాలు, కమల నయనాలు, నాలుగు భుజాలు. ప్రేమగల తల్లిదండ్రులకు బిడ్డ వంగినట్టు ఆయనకు తల వంచుతాం.","hi":"सिर से पाँव तक विष्णु की पूरी छवि — मुकुट, कुंडल, शंख, चक्र, पीतांबर, कमल-नयन, चार भुजाएँ। जैसे बच्चा प्यार करने वाले माता-पिता के आगे झुकता है, वैसे हम उन्हें सिर झुकाते हैं।"},
"vsn_dhyanam_7": {"en":"Now the picture turns to Kṛṣṇa: seated on a golden throne under the heavenly Pārijāta tree, dark as a rain cloud, beautifully adorned —","te":"ఇప్పుడు దృశ్యం శ్రీకృష్ణుని వైపు మళ్ళుతుంది: స్వర్గంలోని పారిజాత వృక్షం కింద బంగారు సింహాసనంపై కూర్చున్న, వర్షమేఘం వలె నల్లని, అందంగా అలంకరించుకున్న —","hi":"अब छवि श्रीकृष्ण की ओर मुड़ती है: स्वर्ग के पारिजात वृक्ष के नीचे स्वर्ण सिंहासन पर बैठे, वर्षा-मेघ जैसे श्याम, सुंदर अलंकारों से सजे —"},
"vsn_dhyanam_8": {"en":"— with a moon-like face, four arms, and Rukmiṇī and Satyabhāmā beside Him. We end the meditation by taking refuge in this Kṛṣṇa — and now the thousand names begin.","te":"— చంద్రుని వంటి ముఖం, నాలుగు భుజాలు, పక్కన రుక్మిణీ సత్యభామలతో ఉన్న శ్రీకృష్ణుని ఆశ్రయిస్తూ ధ్యానం ముగిస్తాం — ఇప్పుడు వేయి నామాలు మొదలవుతాయి.","hi":"— चंद्र जैसा मुख, चार भुजाएँ, साथ में रुक्मिणी और सत्यभामा। इन्हीं श्रीकृष्ण की शरण लेकर ध्यान समाप्त करते हैं — और अब सहस्र नाम शुरू होते हैं।"},
"vsn_1_1": {"en":"The very first name says it all: God is not somewhere far away — He is this whole world and is present in every part of it. He made everything, keeps everything going, and lives inside every being as its true Self.","te":"మొదటి నామమే అంతా చెప్పేస్తుంది: దేవుడు ఎక్కడో దూరంగా లేడు — ఈ ప్రపంచమంతా ఆయనే, దాని ప్రతి భాగంలోనూ ఉన్నాడు. అన్నిటినీ సృష్టించి, నడిపిస్తూ, ప్రతి ప్రాణిలో నిజమైన ఆత్మగా నివసిస్తున్నాడు.","hi":"पहला नाम ही सब कह देता है: भगवान कहीं दूर नहीं — यह पूरा संसार वही हैं और इसके हर कण में हैं। उन्होंने सब बनाया, सब चलाते हैं, और हर प्राणी में उसकी सच्ची आत्मा बनकर रहते हैं।"},
"vsn_2_2": {"en":"God is the pure, silent witness inside each of us — the 'I' that watches everything we think and feel. He is also where every freed soul finally arrives, and He never fades.","te":"దేవుడు మనలో ప్రతి ఒక్కరిలోనూ ఉన్న పవిత్రమైన, నిశ్శబ్ద సాక్షి — మనం ఆలోచించేదీ, అనుభవించేదీ అంతా చూసే ‘నేను’. ముక్తి పొందిన ప్రతి జీవీ చివరకు చేరేది ఆయననే; ఆయన ఎన్నడూ క్షీణించడు.","hi":"भगवान हम सबके भीतर का पवित्र, मौन साक्षी हैं — वह 'मैं' जो हमारे हर विचार और भाव को देखता है। हर मुक्त आत्मा अंत में उन्हीं तक पहुँचती है, और वे कभी क्षीण नहीं होते।"},
"vsn_3_3": {"en":"He is both the goal of yoga and the guide who leads us there. He came as Narasiṃha to save a child devotee, and He is the best of all beings.","te":"యోగానికి లక్ష్యమూ ఆయనే, అక్కడికి నడిపించే మార్గదర్శీ ఆయనే. బాల భక్తుణ్ణి కాపాడడానికి నరసింహునిగా వచ్చాడు; అందరిలో ఉత్తముడు ఆయనే.","hi":"योग का लक्ष्य भी वही हैं और वहाँ तक ले जाने वाले मार्गदर्शक भी। एक बाल-भक्त को बचाने वे नरसिंह बनकर आए, और वे सबमें उत्तम हैं।"},
"vsn_4_4": {"en":"God is everything — the one who starts the world, keeps it, and gathers it back. Yet He is also gentle and auspicious (Śiva), a treasure that never runs out, and the true master of all.","te":"దేవుడే సర్వం — లోకాన్ని మొదలుపెట్టేవాడు, నిలిపేవాడు, మళ్ళీ తనలోకి తీసుకునేవాడు. అయినా సౌమ్యుడు, మంగళకరుడు (శివుడు), ఎన్నటికీ తరగని నిధి, అందరికీ నిజమైన యజమాని.","hi":"भगवान ही सब कुछ हैं — संसार को शुरू करने, चलाने और फिर समेटने वाले। फिर भी वे सौम्य और मंगलमय (शिव) हैं, कभी न घटने वाला ख़ज़ाना, और सबके सच्चे स्वामी।"},
"vsn_5_5": {"en":"Nobody created God — He simply is, without beginning or end. He brings happiness, shines like the sun, has beautiful lotus eyes, and the Vedas are His great voice.","te":"దేవుణ్ణి ఎవరూ సృష్టించలేదు — ఆయన ఉన్నాడు, అంతే; ఆది అంతం లేనివాడు. సుఖాన్ని ఇస్తాడు, సూర్యుని వలె ప్రకాశిస్తాడు, అందమైన తామర కన్నులవాడు; వేదాలే ఆయన గొప్ప స్వరం.","hi":"भगवान को किसी ने नहीं बनाया — वे बस हैं, बिना आदि और अंत। वे सुख देते हैं, सूर्य जैसे चमकते हैं, उनकी सुंदर कमल-आँखें हैं, और वेद उनकी महान वाणी हैं।"},
"vsn_6_6": {"en":"We can never fully measure God. He is the master of our senses — so when we can't control our mind, we can ask Him for help. He shaped this vast world and stays steady through all its changes.","te":"దేవుణ్ణి మనం ఎన్నటికీ పూర్తిగా కొలవలేం. ఆయన మన ఇంద్రియాలకు ప్రభువు — కాబట్టి మనసు మన మాట విననప్పుడు ఆయన సహాయం అడగవచ్చు. ఈ విశాల ప్రపంచాన్ని తీర్చిదిద్ది, అన్ని మార్పులలోనూ స్థిరంగా ఉంటాడు.","hi":"भगवान को हम कभी पूरा नहीं माप सकते। वे हमारी इंद्रियों के स्वामी हैं — इसलिए जब मन वश में न हो, उनसे मदद माँग सकते हैं। उन्होंने यह विशाल संसार गढ़ा और हर बदलाव में स्थिर रहते हैं।"},
"vsn_7_7": {"en":"We can't grab God with our eyes or hands, yet He is eternal and full of every good thing. He is pure and makes us pure — the most auspicious presence there is.","te":"దేవుణ్ణి కన్నులతో, చేతులతో పట్టుకోలేం; అయినా ఆయన శాశ్వతుడు, అన్ని మంచి గుణాలతో నిండినవాడు. ఆయన పవిత్రుడు, మనల్నీ పవిత్రం చేస్తాడు — అన్నిటికంటే మంగళకరమైన సాన్నిధ్యం.","hi":"भगवान को आँखों या हाथों से नहीं पकड़ सकते, फिर भी वे शाश्वत और हर अच्छाई से पूर्ण हैं। वे पवित्र हैं और हमें पवित्र करते हैं — सबसे मंगलमय उपस्थिति।"},
"vsn_8_8": {"en":"Every breath we take is a gift from Him — He is life itself. He is the eldest and best, the father of all creatures, and the protector who defeated the demon Madhu.","te":"మనం తీసుకునే ప్రతి శ్వాసా ఆయన ఇచ్చిన కానుకే — ప్రాణమే ఆయన. అందరికంటే పెద్దవాడు, శ్రేష్ఠుడు, అన్ని ప్రాణులకు తండ్రి, మధు రాక్షసుణ్ణి ఓడించిన రక్షకుడు.","hi":"हमारी हर साँस उनका उपहार है — वे स्वयं जीवन हैं। वे सबसे ज्येष्ठ और श्रेष्ठ, सब प्राणियों के पिता, और मधु दैत्य को हराने वाले रक्षक हैं।"},
"vsn_9_9": {"en":"God is powerful and brave, yet He is also grateful — He remembers even the smallest good thing we offer Him. Nothing can defeat Him, and He is perfectly at peace in Himself.","te":"దేవుడు శక్తిమంతుడు, ధైర్యవంతుడు; అయినా కృతజ్ఞుడు — మనం అర్పించే చిన్న మంచిని కూడా గుర్తుంచుకుంటాడు. ఆయనను ఏదీ ఓడించలేదు; తనలో తాను పూర్తి శాంతిగా ఉంటాడు.","hi":"भगवान शक्तिशाली और वीर हैं, फिर भी कृतज्ञ — हमारी छोटी-से-छोटी भेंट भी याद रखते हैं। उन्हें कोई हरा नहीं सकता, और वे अपने में पूर्ण शांत हैं।"},
"vsn_10_10": {"en":"When life is hard, He is our shelter and our real happiness. He is time itself — every day and every year — and He sees everything, so nothing we go through is unseen.","te":"జీవితం కష్టంగా ఉన్నప్పుడు ఆయనే మన ఆశ్రయం, మన నిజమైన ఆనందం. ప్రతి రోజూ, ప్రతి సంవత్సరం — కాలమే ఆయన; అన్నిటినీ చూస్తాడు, కాబట్టి మనం పడే కష్టమేదీ ఆయనకు కనిపించకుండా పోదు.","hi":"जब जीवन कठिन हो, वही हमारा आश्रय और सच्चा सुख हैं। हर दिन, हर वर्ष — वे स्वयं समय हैं, और सब देखते हैं, इसलिए हम जो भी झेलते हैं वह अनदेखा नहीं।"},
"vsn_11_11": {"en":"God was never born and never falls from His greatness (Acyuta). He is the beginning of everything and the result of all effort — and every sincere path, whatever it is, leads to Him.","te":"దేవుడు పుట్టలేదు, తన మహిమ నుండి ఎన్నడూ జారడు (అచ్యుతుడు). అన్నిటికీ ఆరంభం, అన్ని ప్రయత్నాలకూ ఫలం ఆయనే — నిజాయితీగల ఏ మార్గమైనా ఆయన దగ్గరకే చేరుస్తుంది.","hi":"भगवान का कभी जन्म नहीं हुआ और वे अपनी महिमा से कभी नहीं गिरते (अच्युत)। सबका आरंभ और हर प्रयास का फल वही हैं — हर सच्चा मार्ग, जो भी हो, उन्हीं तक ले जाता है।"},
"vsn_12_12": {"en":"He lives in everyone and everyone lives in Him, so He treats all equally. He is truth itself, nothing He does is ever wasted, and every action of His is good.","te":"ఆయన అందరిలో ఉన్నాడు, అందరూ ఆయనలో ఉన్నారు; అందుకే అందరినీ సమానంగా చూస్తాడు. సత్యమే ఆయన; ఆయన చేసేదేదీ వ్యర్థం కాదు; ఆయన ప్రతి పనీ ధర్మమే.","hi":"वे सबमें रहते हैं और सब उनमें, इसलिए सबको समान मानते हैं। वे स्वयं सत्य हैं, उनका कोई काम व्यर्थ नहीं जाता, और उनका हर कर्म धर्म है।"},
"vsn_13_13": {"en":"God can be fierce (Rudra) to protect what is right, yet He also wipes away our tears. His names are pure to hear, He never dies, and He is the highest place a soul can reach.","te":"ధర్మాన్ని కాపాడడానికి దేవుడు ఉగ్రుడవుతాడు (రుద్రుడు), అయినా మన కన్నీళ్ళు తుడుస్తాడు. ఆయన నామాలు వినడానికే పవిత్రం; ఆయనకు మరణం లేదు; జీవుడు చేరగల అత్యున్నత స్థానం ఆయనే.","hi":"धर्म की रक्षा के लिए भगवान उग्र (रुद्र) भी बनते हैं, फिर भी हमारे आँसू पोंछते हैं। उनके नाम सुनना ही पवित्र है, वे अमर हैं, और आत्मा का सर्वोच्च स्थान वही हैं।"},
"vsn_14_14": {"en":"He is everywhere and knows everything. All the knowledge in the Vedas is really about Him — He is the Veda itself, and the wise seer who sees all.","te":"ఆయన అంతటా ఉన్నాడు, అన్నీ తెలిసినవాడు. వేదాలలోని జ్ఞానమంతా నిజానికి ఆయన గురించే — వేదమే ఆయన, అన్నిటినీ చూసే జ్ఞాని ఆయనే.","hi":"वे सर्वत्र हैं और सब जानते हैं। वेदों का सारा ज्ञान वास्तव में उन्हीं के बारे में है — वे स्वयं वेद हैं, और सब देखने वाले ज्ञानी कवि।"},
"vsn_15_15": {"en":"He watches over the world, the gods and right-and-wrong, so every good deed is noticed. He appears in fours — four arms, four forms — protecting us from every side.","te":"లోకాలనూ దేవతలనూ ధర్మాధర్మాలనూ ఆయన గమనిస్తూ ఉంటాడు — కాబట్టి ప్రతి మంచి పనీ ఆయనకు తెలుస్తుంది. నాలుగు భుజాలు, నాలుగు రూపాలతో అన్ని వైపుల నుండీ మనల్ని కాపాడుతాడు.","hi":"वे संसार, देवताओं और धर्म-अधर्म पर नज़र रखते हैं, इसलिए हर अच्छा काम उन्हें दिखता है। चार भुजाओं और चार रूपों में वे हर ओर से हमारी रक्षा करते हैं।"},
"vsn_16_16": {"en":"He is the food that nourishes us and the one who enjoys it in us. He is patient with our mistakes, always victorious, and comes back again and again to help the world.","te":"మనల్ని పోషించే అన్నమూ ఆయనే, మనలో దాన్ని అనుభవించేదీ ఆయనే. మన తప్పులను ఓర్పుతో భరిస్తాడు, ఎప్పుడూ జయిస్తాడు, లోకానికి సహాయం చేయడానికి మళ్ళీ మళ్ళీ వస్తాడు.","hi":"हमें पोषण देने वाला अन्न भी वही हैं और हममें उसका आनंद लेने वाले भी। वे हमारी गलतियों पर धैर्य रखते हैं, सदा विजयी हैं, और संसार की मदद को बार-बार आते हैं।"},
"vsn_17_17": {"en":"As little Vāmana, He came humbly as a small boy and then grew to fill the universe. Small or huge, He is always pure, powerful, and keeps the whole world in order.","te":"వామనునిగా చిన్న బాలునిలా వినయంగా వచ్చి, తర్వాత విశ్వమంతా నిండేలా పెరిగాడు. చిన్నగా ఉన్నా, అతి పెద్దగా ఉన్నా — ఎప్పుడూ పవిత్రుడు, శక్తిమంతుడు, లోకాన్ని క్రమంలో ఉంచేవాడు.","hi":"वामन बनकर वे एक छोटे बालक के रूप में विनम्रता से आए और फिर पूरे विश्व में फैल गए। छोटे हों या विराट — सदा पवित्र, शक्तिशाली, और संसार को व्यवस्था में रखने वाले।"},
"vsn_18_18": {"en":"He is the one truly worth knowing, and also the healer of the soul's sickness. Sweet as honey to those who love Him, mighty against those who do harm.","te":"నిజంగా తెలుసుకోదగినవాడు ఆయనే; ఆత్మ రోగాన్ని నయం చేసే వైద్యుడూ ఆయనే. ప్రేమించేవారికి తేనె వంటి మధురుడు, హాని చేసేవారి ఎదుట మహాబలుడు.","hi":"सच में जानने योग्य वही हैं, और आत्मा के रोग के वैद्य भी। प्रेम करने वालों के लिए मधु जैसे मीठे, बुराई करने वालों के सामने महाबली।"},
"vsn_19_19": {"en":"His wisdom, strength and brightness are beyond any limit, and His form can't be fully described in words. He lifted mountains — Govardhana to shelter His people — so no burden is too heavy for Him.","te":"ఆయన జ్ఞానం, బలం, తేజస్సు అపరిమితం; ఆయన రూపాన్ని మాటల్లో పూర్తిగా చెప్పలేం. తన ప్రజలకు నీడనివ్వడానికి గోవర్ధనాన్ని ఎత్తినవాడు — ఆయనకు ఏ భారమూ మరీ బరువు కాదు.","hi":"उनकी बुद्धि, शक्ति और तेज की कोई सीमा नहीं, और उनका रूप शब्दों में पूरा नहीं कहा जा सकता। उन्होंने अपने लोगों को बचाने गोवर्धन उठाया — उनके लिए कोई भार भारी नहीं।"},
"vsn_20_20": {"en":"He is Govinda — the protector of cows and of the earth, and the refuge of all good people. Lakṣmī lives in His heart, and nothing can stand in His way when He comes to help.","te":"ఆయన గోవిందుడు — గోవులనూ భూమినీ కాపాడేవాడు, సజ్జనులందరికీ ఆశ్రయం. ఆయన హృదయంలో లక్ష్మి నివసిస్తుంది; సహాయానికి వచ్చినప్పుడు ఆయనను ఏదీ అడ్డుకోలేదు.","hi":"वे गोविंद हैं — गौओं और पृथ्वी के रक्षक, और सब सज्जनों का आश्रय। उनके हृदय में लक्ष्मी बसती हैं, और जब वे मदद को आते हैं तो उन्हें कुछ नहीं रोक सकता।"},
"vsn_21_21": {"en":"He is like a swan that removes our fear of this world, the light within all lights, and the one who tames what is wild in us. All creatures are His children.","te":"ఈ లోక భయాన్ని పోగొట్టే హంస వంటివాడు, అన్ని వెలుగులలోని వెలుగు, మనలోని అదుపులేనితనాన్ని అణచేవాడు. అన్ని ప్రాణులూ ఆయన బిడ్డలే.","hi":"वे उस हंस जैसे हैं जो इस संसार का भय दूर करता है, सब प्रकाशों का प्रकाश, और हमारे भीतर के जंगलीपन को वश में करने वाले। सब प्राणी उनकी संतान हैं।"},
"vsn_22_22": {"en":"He sees all and is never touched by death. Brave as a lion, He makes sure every action brings its fair result. He is the true teacher and guide of the world.","te":"ఆయన అన్నిటినీ చూస్తాడు, మృత్యువు ఆయనను తాకదు. సింహం వంటి ధైర్యంతో ప్రతి కర్మకూ న్యాయమైన ఫలం వచ్చేలా చూస్తాడు. లోకానికి నిజమైన గురువు, మార్గదర్శి ఆయనే.","hi":"वे सब देखते हैं और मृत्यु उन्हें छू नहीं सकती। सिंह जैसे वीर, वे सुनिश्चित करते हैं कि हर कर्म का उचित फल मिले। संसार के सच्चे गुरु और मार्गदर्शक वही हैं।"},
"vsn_23_23": {"en":"He is the greatest teacher — even teachers learn from Him. He is truth, His strength never fails, and He is always awake, watching over us.","te":"ఆయనే గొప్ప గురువు — గురువులు కూడా ఆయన నుండే నేర్చుకుంటారు. సత్యమే ఆయన, ఆయన బలం ఎన్నడూ విఫలం కాదు, ఎప్పుడూ మేల్కొని మనల్ని కాపాడుతూ ఉంటాడు.","hi":"वे सबसे बड़े गुरु हैं — गुरु भी उन्हीं से सीखते हैं। वे सत्य हैं, उनका बल कभी विफल नहीं होता, और वे सदा जागकर हमारी रक्षा करते हैं।"},
"vsn_24_24": {"en":"He leads the way and guides everyone fairly. With a thousand heads, eyes and feet, He is everywhere at once — the soul of the whole universe.","te":"ఆయనే దారి చూపిస్తాడు, అందరినీ న్యాయంగా నడిపిస్తాడు. వేయి శిరస్సులు, కన్నులు, పాదాలతో ఒకేసారి అంతటా ఉన్నాడు — విశ్వమంతటికీ ఆత్మ.","hi":"वे राह दिखाते हैं और सबको न्याय से ले चलते हैं। हज़ार सिर, आँखों और पैरों से वे एक साथ सर्वत्र हैं — पूरे विश्व की आत्मा।"},
"vsn_25_25": {"en":"He turns the wheel of life, yet is never caught in it. We can't see Him because of our own ignorance — like the sun hidden by clouds — but He is always there, holding up the earth.","te":"జీవిత చక్రాన్ని తిప్పేవాడు ఆయనే, అయినా అందులో చిక్కుకోడు. మన అజ్ఞానం వల్లే ఆయన కనిపించడు — మేఘాల వెనుక సూర్యునిలా — కానీ ఎప్పుడూ అక్కడే ఉండి భూమిని ధరిస్తున్నాడు.","hi":"जीवन का चक्र वही घुमाते हैं, फिर भी उसमें फँसते नहीं। अपने अज्ञान के कारण हम उन्हें नहीं देख पाते — बादलों में छिपे सूर्य की तरह — पर वे सदा वहीं हैं, पृथ्वी को थामे।"},
"vsn_26_26": {"en":"He is gracious even to those who wrong Him and always calm. He honours good people and is honoured by them. As Nara-Nārāyaṇa, He is our friend and shelter.","te":"తనకు అపకారం చేసినవారిపైనా అనుగ్రహం చూపేవాడు, ఎప్పుడూ ప్రశాంతుడు. సజ్జనులను గౌరవిస్తాడు, వారిచేత గౌరవించబడతాడు. నరనారాయణునిగా మనకు మిత్రుడు, ఆశ్రయం.","hi":"जो उनका बुरा करते हैं उन पर भी वे कृपा करते हैं, और सदा शांत रहते हैं। वे सज्जनों का सम्मान करते हैं और उनसे सम्मान पाते हैं। नर-नारायण रूप में वे हमारे मित्र और आश्रय हैं।"},
"vsn_27_27": {"en":"Whatever He decides always comes true. He gives success to those who try sincerely — and He is also the way to that success.","te":"ఆయన ఏది సంకల్పిస్తే అది నిజమవుతుంది. నిజాయితీగా ప్రయత్నించేవారికి విజయం ఇస్తాడు — ఆ విజయానికి మార్గమూ ఆయనే.","hi":"वे जो भी संकल्प करते हैं, वह सच होता है। सच्चे मन से प्रयास करने वालों को वे सफलता देते हैं — और उस सफलता का रास्ता भी वही हैं।"},
"vsn_28_28": {"en":"He rains blessings on His devotees like a generous cloud. Dharma is the staircase that leads to Him, and all the wisdom of the Vedas is like an ocean around Him.","te":"ఉదారమైన మేఘంలా భక్తులపై ఆశీస్సులు కురిపిస్తాడు. ఆయనను చేరే మెట్లు ధర్మమే; వేదాల జ్ఞానమంతా ఆయన చుట్టూ ఉన్న సముద్రం వంటిది.","hi":"वे उदार बादल की तरह भक्तों पर आशीर्वाद बरसाते हैं। धर्म उन तक पहुँचने की सीढ़ी है, और वेदों का सारा ज्ञान उनके चारों ओर सागर जैसा है।"},
"vsn_29_29": {"en":"His strong arms protect the world. He gives wealth, but He is the real wealth. He takes many forms and lights up everything — including our understanding.","te":"ఆయన బలమైన భుజాలు లోకాన్ని కాపాడుతాయి. ఆయన సంపద ఇస్తాడు, కానీ నిజమైన సంపద ఆయనే. అనేక రూపాలు ధరించి అన్నిటినీ — మన అవగాహనను కూడా — వెలిగిస్తాడు.","hi":"उनकी मज़बूत भुजाएँ संसार की रक्षा करती हैं। वे धन देते हैं, पर सच्चा धन वही हैं। वे अनेक रूप लेते हैं और सबको — हमारी समझ को भी — प्रकाशित करते हैं।"},
"vsn_30_30": {"en":"Strength, brilliance and light all come from Him. He is the sacred sound Om, cool and soothing like moonlight, bright like the sun.","te":"బలం, తేజస్సు, వెలుగు అన్నీ ఆయన నుండే వస్తాయి. పవిత్రమైన ఓంకారం ఆయనే — వెన్నెల వలె చల్లగా, సూర్యుని వలె ప్రకాశంగా.","hi":"बल, तेज और प्रकाश सब उन्हीं से आते हैं। वे पवित्र ॐ हैं — चाँदनी जैसे शीतल, सूर्य जैसे उज्ज्वल।"},
"vsn_31_31": {"en":"He is the medicine for the pain of life and the bridge that carries us across it. Everything He does is true and right.","te":"జీవితపు బాధకు ఔషధం ఆయనే; దాన్ని దాటించే వారధి ఆయనే. ఆయన చేసే ప్రతిదీ సత్యం, ధర్మం.","hi":"जीवन के दुःख की औषधि वही हैं, और उसे पार कराने वाला पुल भी। उनका हर काम सत्य और धर्ममय है।"},
"vsn_32_32": {"en":"He is the master of past, present and future. He grants our good wishes, removes harmful desires, and is the most lovable one of all.","te":"భూత భవిష్యత్ వర్తమానాలకు ఆయనే యజమాని. మంచి కోరికలు తీరుస్తాడు, హానికరమైన కోరికలను తొలగిస్తాడు; అందరికంటే ప్రేమించదగినవాడు ఆయనే.","hi":"भूत, भविष्य और वर्तमान के स्वामी वही हैं। वे अच्छी इच्छाएँ पूरी करते हैं, हानिकारक कामनाएँ हटाते हैं, और सबसे प्यारे वही हैं।"},
"vsn_33_33": {"en":"He makes the ages begin and turn. Though we can't see Him, He also shows Himself in forms we can see — and He conquers any number of troubles.","te":"యుగాలను మొదలుపెట్టి తిప్పేవాడు ఆయనే. మనకు కనిపించకపోయినా, మనం చూడగలిగే రూపాలలో కూడా దర్శనమిస్తాడు — ఎన్ని కష్టాలనైనా జయిస్తాడు.","hi":"युगों को शुरू करने और घुमाने वाले वही हैं। दिखाई न देकर भी वे ऐसे रूपों में प्रकट होते हैं जो हम देख सकें — और कितनी भी मुसीबतों को जीत लेते हैं।"},
"vsn_34_34": {"en":"He is dear to all and loved by the wise. As Kṛṣṇa He wore a peacock feather. He calms our anger, yet shows anger against injustice — and His arms are everywhere to help.","te":"ఆయన అందరికీ ప్రియుడు, జ్ఞానులకు ఇష్టుడు. శ్రీకృష్ణునిగా నెమలి పింఛం ధరించాడు. మన కోపాన్ని చల్లారుస్తాడు, అన్యాయంపై కోపం చూపిస్తాడు — సహాయానికి ఆయన భుజాలు అంతటా ఉన్నాయి.","hi":"वे सबके प्रिय और ज्ञानियों के प्यारे हैं। कृष्ण रूप में उन्होंने मोरपंख पहना। वे हमारा क्रोध शांत करते हैं, फिर भी अन्याय पर क्रोध दिखाते हैं — और मदद को उनकी भुजाएँ सर्वत्र हैं।"},
"vsn_35_35": {"en":"He never slips or fails. He is our breath and the one who gives it. Ever watchful, He is the firm ground everything stands on.","te":"ఆయన ఎన్నడూ జారడు, విఫలం కాడు. మన శ్వాసా ఆయనే, దాన్ని ఇచ్చేదీ ఆయనే. ఎప్పుడూ జాగ్రత్తగా ఉండి, అన్నీ నిలిచిన దృఢమైన పునాదిగా ఉంటాడు.","hi":"वे कभी नहीं फिसलते, कभी विफल नहीं होते। हमारी साँस वही हैं और उसे देने वाले भी। सदा सजग, वे वह ठोस आधार हैं जिस पर सब टिका है।"},
"vsn_36_36": {"en":"He carries the weight of the world and gives boons to those who ask. He is Vāsudeva, the first God, shining with great light.","te":"లోక భారాన్ని ఆయనే మోస్తాడు, అడిగినవారికి వరాలు ఇస్తాడు. ఆయన వాసుదేవుడు, ఆదిదేవుడు, గొప్ప వెలుగుతో ప్రకాశించేవాడు.","hi":"वे संसार का भार उठाते हैं और माँगने वालों को वर देते हैं। वे वासुदेव हैं, आदिदेव, महान प्रकाश से दीप्त।"},
"vsn_37_37": {"en":"He has no sorrow, and He helps us cross over ours. A brave hero and Lord of all people, He is always on our side, with eyes as gentle as lotuses.","te":"ఆయనకు దుఃఖం లేదు; మన దుఃఖాన్ని దాటడానికి సహాయం చేస్తాడు. ధైర్యశాలి, అందరికీ ఈశ్వరుడు, ఎప్పుడూ మన పక్షానే ఉంటాడు — తామరల వంటి కోమలమైన కన్నులతో.","hi":"उन्हें कोई शोक नहीं, और वे हमें अपने शोक से पार कराते हैं। वीर नायक और सबके स्वामी, वे सदा हमारे साथ हैं, कमल जैसी कोमल आँखों वाले।"},
"vsn_38_38": {"en":"He sits in the lotus of our heart and cares for every body as His own. Rich in every blessing, He rides on Garuḍa, His flag flying high.","te":"మన హృదయ పద్మంలో కూర్చుని, ప్రతి శరీరాన్నీ తనదిగా చూసుకుంటాడు. అన్ని ఆశీస్సులతో సంపన్నుడు; గరుడునిపై సంచరిస్తాడు, ఆయన పతాకం ఎత్తుగా ఎగురుతుంది.","hi":"वे हमारे हृदय-कमल में बैठते हैं और हर शरीर की अपने जैसी देखभाल करते हैं। हर आशीर्वाद से संपन्न, वे गरुड़ पर सवार हैं, उनका ध्वज ऊँचा लहराता है।"},
"vsn_39_39": {"en":"There is no one like Him. He knows the right time for everything, takes away our sins (Hari), carries every auspicious mark, and always wins against evil.","te":"ఆయన వంటివారు ఎవరూ లేరు. ప్రతి పనికీ సరైన సమయం ఆయనకు తెలుసు; మన పాపాలను హరిస్తాడు (హరి); అన్ని శుభ లక్షణాలు గలవాడు; చెడుపై ఎప్పుడూ గెలుస్తాడు.","hi":"उनके जैसा कोई नहीं। वे हर बात का सही समय जानते हैं, हमारे पाप हरते हैं (हरि), हर शुभ लक्षण वाले हैं, और बुराई पर सदा जीतते हैं।"},
"vsn_40_40": {"en":"He is the path and the reason for everything. As little Dāmodara, He let His mother tie Him with a rope — the Almighty bound by love. Patient and swift, He bears all.","te":"మార్గమూ ఆయనే, అన్నిటికీ కారణమూ ఆయనే. చిన్న దామోదరునిగా తల్లి తాడుతో కట్టేయడానికి ఒప్పుకున్నాడు — సర్వ శక్తిమంతుడు ప్రేమకు కట్టుబడ్డాడు. ఓర్పు గలవాడు, వేగవంతుడు, అన్నీ భరిస్తాడు.","hi":"वही मार्ग हैं और सबका कारण। नन्हे दामोदर के रूप में उन्होंने माँ को रस्सी से बाँधने दिया — सर्वशक्तिमान प्रेम से बँधे। धैर्यवान और वेगवान, वे सब सहते हैं।"},
"vsn_41_41": {"en":"Everything comes from Him — He is the maker, the tools and the cause. Yet He is deep and hidden, like a treasure we have to look for within.","te":"అన్నీ ఆయన నుండే వస్తాయి — చేసేవాడూ, పనిముట్లూ, కారణమూ ఆయనే. అయినా ఆయన లోతుగా, దాగి ఉన్నాడు — లోపల వెతికి కనుక్కోవలసిన నిధిలా.","hi":"सब उन्हीं से आता है — वे कर्ता, साधन और कारण हैं। फिर भी वे गहरे और छिपे हैं, एक ख़ज़ाने की तरह जिसे भीतर खोजना पड़ता है।"},
"vsn_42_42": {"en":"He keeps the order of the world and gives everyone their rightful place, like He gave Dhruva his place among the stars. He is content, complete, and His glance brings blessings.","te":"లోక వ్యవస్థను ఆయనే నిలుపుతాడు, ధ్రువునికి నక్షత్రాలలో స్థానం ఇచ్చినట్టు, అందరికీ తగిన స్థానం ఇస్తాడు. ఆయన తృప్తుడు, పరిపూర్ణుడు; ఆయన చూపే ఆశీర్వాదం.","hi":"वे संसार की व्यवस्था बनाए रखते हैं और सबको उचित स्थान देते हैं, जैसे ध्रुव को तारों में स्थान दिया। वे संतुष्ट और पूर्ण हैं, और उनकी दृष्टि ही आशीर्वाद है।"},
"vsn_43_43": {"en":"He is Rāma, the one in whom everyone finds joy and rest. Pure and free of passion, He is the path, the guide and the bravest of the brave — dharma in person.","te":"అందరూ ఆనందాన్నీ విశ్రాంతినీ పొందే రాముడు ఆయనే. రజోగుణం లేని పవిత్రుడు; మార్గమూ, మార్గదర్శీ, వీరులలో వీరుడూ ఆయనే — ధర్మం మూర్తీభవించినవాడు.","hi":"वे राम हैं, जिनमें सब आनंद और विश्राम पाते हैं। पवित्र और रजोगुण से मुक्त, वे मार्ग हैं, मार्गदर्शक हैं, वीरों में वीर — साक्षात धर्म।"},
"vsn_44_44": {"en":"He is the Lord of Vaikuṇṭha and the sacred sound Om. He gives life and is beyond what our senses can know — yet He is as close as the air we breathe.","te":"వైకుంఠ నాథుడు, పవిత్ర ఓంకారం ఆయనే. ప్రాణం ఇచ్చేవాడు, మన ఇంద్రియాలకు అందనివాడు — అయినా మనం పీల్చే గాలంత దగ్గరగా ఉంటాడు.","hi":"वे वैकुंठनाथ हैं और पवित्र ॐ। वे जीवन देते हैं और इंद्रियों की पहुँच से परे हैं — फिर भी उतने ही पास जितनी हमारी साँस की हवा।"},
"vsn_45_45": {"en":"He is time itself — the seasons and the years. He holds the Sudarśana discus, can be fierce when needed, and is the place where tired souls find rest.","te":"కాలమే ఆయన — ఋతువులూ సంవత్సరాలూ. సుదర్శన చక్రం ధరించినవాడు, అవసరమైనప్పుడు ఉగ్రుడవుతాడు; అలసిన జీవులు విశ్రాంతి పొందే చోటు ఆయనే.","hi":"वे स्वयं समय हैं — ऋतुएँ और वर्ष। वे सुदर्शन चक्र धारण करते हैं, ज़रूरत हो तो उग्र भी होते हैं, और थकी आत्माओं का विश्राम-स्थल वही हैं।"},
"vsn_46_46": {"en":"The whole universe spreads out from Him like a tree from a seed that never dies. He is what everyone is searching for, while He Himself needs nothing.","te":"ఎన్నటికీ నశించని బీజం నుండి చెట్టు పెరిగినట్టు విశ్వమంతా ఆయన నుండే విస్తరిస్తుంది. అందరూ వెతికేది ఆయననే; ఆయనకు మాత్రం ఏమీ అవసరం లేదు.","hi":"जैसे कभी न नष्ट होने वाले बीज से पेड़ फैलता है, वैसे ही सारा विश्व उनसे फैलता है। सब जिसे खोज रहे हैं वह वही हैं, जबकि उन्हें स्वयं कुछ नहीं चाहिए।"},
"vsn_47_47": {"en":"He never gets tired of caring for us. The stars circle around Him, and He is always working for the good of the world.","te":"మనల్ని చూసుకోవడంలో ఆయనకు ఎన్నడూ అలసట లేదు. నక్షత్రాలు ఆయన చుట్టూ తిరుగుతాయి; లోక హితం కోసం ఎప్పుడూ పనిచేస్తూనే ఉంటాడు.","hi":"हमारी देखभाल करते-करते वे कभी नहीं थकते। तारे उनके चारों ओर घूमते हैं, और वे सदा संसार के भले के लिए काम करते रहते हैं।"},
"vsn_48_48": {"en":"Every act of worship is really offered to Him — He is the worship and the worshipped. He sees all, is completely free, and is the highest knowledge.","te":"ప్రతి పూజా నిజానికి ఆయనకే — పూజా ఆయనే, పూజించబడేదీ ఆయనే. అన్నిటినీ చూస్తాడు, పూర్తిగా ముక్తుడు, అత్యున్నత జ్ఞానం ఆయనే.","hi":"हर पूजा वास्तव में उन्हीं को अर्पित होती है — वे पूजा भी हैं और पूज्य भी। वे सब देखते हैं, पूर्ण मुक्त हैं, और सर्वोच्च ज्ञान हैं।"},
"vsn_49_49": {"en":"He keeps His promises, has a kind face, and is a true friend who helps without expecting anything back. He has conquered anger — and steals our hearts.","te":"ఆయన మాట నిలబెట్టుకుంటాడు, దయగల ముఖం గలవాడు, ఏమీ ఆశించకుండా సహాయం చేసే నిజమైన మిత్రుడు. కోపాన్ని జయించినవాడు — మన హృదయాలను దోచుకునేవాడు.","hi":"वे अपने वचन निभाते हैं, उनका चेहरा दयालु है, और वे बिना कुछ चाहे मदद करने वाले सच्चे मित्र हैं। उन्होंने क्रोध जीत लिया है — और हमारा मन चुरा लेते हैं।"},
"vsn_50_50": {"en":"He loves His devotees like a parent loves a child. He is free, everywhere, does countless things, and holds all the riches of the world.","te":"తల్లిదండ్రులు బిడ్డను ప్రేమించినట్టు ఆయన భక్తులను ప్రేమిస్తాడు. స్వతంత్రుడు, అంతటా ఉన్నవాడు, లెక్కలేనన్ని పనులు చేసేవాడు, లోకంలోని సంపదలన్నీ ఆయనవే.","hi":"वे अपने भक्तों से वैसे प्रेम करते हैं जैसे माता-पिता बच्चे से। वे स्वतंत्र हैं, सर्वत्र हैं, अनगिनत काम करते हैं, और संसार का सारा धन उनका है।"},
"vsn_51_51": {"en":"He protects dharma and lives by it Himself, setting the example. Everything — what lasts and what passes — is held in Him.","te":"ధర్మాన్ని కాపాడుతాడు, స్వయంగా ఆచరించి ఆదర్శంగా నిలుస్తాడు. నిలిచేదీ, గడిచిపోయేదీ — అన్నీ ఆయనలోనే ఉన్నాయి.","hi":"वे धर्म की रक्षा करते हैं और स्वयं उसे जीकर उदाहरण बनते हैं। जो टिकता है और जो बीत जाता है — सब उन्हीं में है।"},
"vsn_52_52": {"en":"He is the God of gods, the great God, and the teacher of all. Strong as a lion, He stays rooted in goodness and peace.","te":"ఆయన దేవదేవుడు, మహాదేవుడు, అందరికీ గురువు. సింహంలా బలవంతుడు, మంచితనంలో, శాంతిలో స్థిరంగా ఉంటాడు.","hi":"वे देवों के देव, महादेव और सबके गुरु हैं। सिंह जैसे बलवान, वे भलाई और शांति में दृढ़ हैं।"},
"vsn_53_53": {"en":"He lifts us out of our troubles and protects the earth. We reach Him through understanding, and He is the most ancient one — yet ever new.","te":"కష్టాల నుండి మనల్ని పైకి లేపుతాడు, భూమిని కాపాడుతాడు. అవగాహనతో ఆయనను చేరుకుంటాం; ఆయన అతి పురాతనుడు — అయినా ఎప్పుడూ నవీనుడే.","hi":"वे हमें मुसीबतों से उबारते हैं और पृथ्वी की रक्षा करते हैं। हम समझ से उन तक पहुँचते हैं, और वे सबसे प्राचीन हैं — फिर भी सदा नए।"},
"vsn_54_54": {"en":"He always keeps His word (Satyasandha) and is the best among the great. He guides us gently, and He is the beloved Lord of His devotees.","te":"ఆయన ఎప్పుడూ మాట నిలబెట్టుకుంటాడు (సత్యసంధుడు), గొప్పవారిలో ఉత్తముడు. మెల్లగా మార్గం చూపిస్తాడు; భక్తులకు ప్రియమైన ప్రభువు.","hi":"वे सदा अपना वचन निभाते हैं (सत्यसंध) और महानों में श्रेष्ठ हैं। वे हमें धीरे से राह दिखाते हैं, और भक्तों के प्रिय प्रभु हैं।"},
"vsn_55_55": {"en":"He is Mukunda — the giver of freedom — and the witness of all we do. Endless as the ocean, He rests on the waters, peaceful and limitless.","te":"ముక్తినిచ్చే ముకుందుడు ఆయనే; మనం చేసే ప్రతిదానికీ సాక్షి. సముద్రమంత అనంతుడు, జలాలపై ప్రశాంతంగా, అపరిమితంగా విశ్రమిస్తాడు.","hi":"वे मुकुंद हैं — मुक्ति देने वाले — और हमारे हर कर्म के साक्षी। सागर जैसे अनंत, वे जल पर शांत और असीम विश्राम करते हैं।"},
"vsn_56_56": {"en":"He is pure joy and spreads joy everywhere. As Trivikrama He measured the worlds in three steps — and He has conquered every enemy.","te":"ఆయన స్వచ్ఛమైన ఆనందం, అంతటా ఆనందం పంచుతాడు. త్రివిక్రమునిగా మూడు అడుగులతో లోకాలను కొలిచాడు — ప్రతి శత్రువునూ జయించాడు.","hi":"वे शुद्ध आनंद हैं और सर्वत्र आनंद बाँटते हैं। त्रिविक्रम रूप में उन्होंने तीन पगों में लोक नापे — और हर शत्रु को जीत लिया।"},
"vsn_57_57": {"en":"He came as the sage Kapila to teach wisdom. He cares for the earth, watches over the gods, and puts an end to death itself.","te":"జ్ఞానాన్ని బోధించడానికి కపిల మహర్షిగా వచ్చాడు. భూమిని చూసుకుంటాడు, దేవతలను పర్యవేక్షిస్తాడు, మృత్యువుకే అంతం చేస్తాడు.","hi":"वे ज्ञान सिखाने कपिल मुनि बनकर आए। वे पृथ्वी की देखभाल करते हैं, देवताओं पर नज़र रखते हैं, और स्वयं मृत्यु का अंत करते हैं।"},
"vsn_58_58": {"en":"As the great Boar (Varāha), He dived into the ocean to rescue the earth. Deep and mysterious, He always carries His discus and mace to protect us.","te":"మహా వరాహునిగా భూమిని కాపాడడానికి సముద్రంలోకి దూకాడు. లోతైనవాడు, రహస్యమైనవాడు; మనల్ని కాపాడడానికి ఎప్పుడూ చక్రం, గద ధరించి ఉంటాడు.","hi":"महावराह बनकर वे पृथ्वी को बचाने सागर में कूदे। गहरे और रहस्यमय, वे हमारी रक्षा के लिए सदा चक्र और गदा धारण करते हैं।"},
"vsn_59_59": {"en":"He is Kṛṣṇa and Saṅkarṣaṇa (Balarāma), never defeated, firm as a deep-rooted tree. His heart is big enough to hold creation, care and dissolution with a single thought.","te":"శ్రీకృష్ణుడూ సంకర్షణుడూ (బలరాముడు) ఆయనే; ఎన్నడూ ఓడనివాడు, లోతుగా వేళ్ళూనిన చెట్టులా స్థిరుడు. ఒక్క ఆలోచనతో సృష్టి, పోషణ, లయం చేయగలిగేంత విశాల హృదయం గలవాడు.","hi":"वे कृष्ण और संकर्षण (बलराम) हैं, कभी पराजित नहीं, गहरी जड़ वाले पेड़ जैसे दृढ़। उनका हृदय इतना बड़ा है कि एक संकल्प से सृष्टि, पालन और लय कर दें।"},
"vsn_60_60": {"en":"He is Bhagavān — full of every divine quality. As Balarāma He carried the plough; He wears a garland of forest flowers and shines like the sun, patient with all.","te":"ఆయన భగవంతుడు — అన్ని దివ్య గుణాలతో నిండినవాడు. బలరామునిగా నాగలి ధరించాడు; వనమాల ధరించి సూర్యుని వలె ప్రకాశిస్తాడు, అందరి పట్లా ఓర్పు గలవాడు.","hi":"वे भगवान हैं — हर दिव्य गुण से पूर्ण। बलराम रूप में उन्होंने हल धारण किया; वे वन-पुष्पों की माला पहनते हैं, सूर्य जैसे चमकते हैं, और सबके प्रति धैर्यवान हैं।"},
"vsn_61_61": {"en":"He came as Paraśurāma with an axe to stop cruel kings, and as Vyāsa to give us the scriptures. He gives wealth generously and reaches up to the heavens.","te":"క్రూరులైన రాజులను ఆపడానికి గొడ్డలితో పరశురామునిగా, మనకు శాస్త్రాలు ఇవ్వడానికి వ్యాసునిగా వచ్చాడు. ఉదారంగా సంపద ఇస్తాడు; స్వర్గం వరకు వ్యాపించినవాడు.","hi":"क्रूर राजाओं को रोकने वे परशु लेकर परशुराम बने, और हमें शास्त्र देने व्यास बने। वे उदारता से धन देते हैं और स्वर्ग तक फैले हैं।"},
"vsn_62_62": {"en":"He is the medicine and the doctor for the suffering of life. In Him is perfect calm and peace — the final shelter we are all looking for.","te":"జీవిత బాధకు ఔషధమూ, వైద్యుడూ ఆయనే. ఆయనలో సంపూర్ణ ప్రశాంతత, శాంతి ఉన్నాయి — మనమందరం వెతుకుతున్న చివరి ఆశ్రయం ఆయనే.","hi":"जीवन के दुःख की औषधि भी वही हैं और वैद्य भी। उनमें पूर्ण शांति है — वह अंतिम आश्रय जिसे हम सब खोज रहे हैं।"},
"vsn_63_63": {"en":"He brings peace and loves all creatures, especially the gentle cow. He rests peacefully on the waters and delights in goodness.","te":"ఆయన శాంతినిస్తాడు, అన్ని ప్రాణులనూ — ముఖ్యంగా సాధువైన గోవును — ప్రేమిస్తాడు. జలాలపై ప్రశాంతంగా విశ్రమిస్తాడు, మంచితనంలో ఆనందిస్తాడు.","hi":"वे शांति देते हैं और सब प्राणियों से — ख़ासकर कोमल गाय से — प्रेम करते हैं। वे जल पर शांति से विश्राम करते हैं और भलाई में आनंद पाते हैं।"},
"vsn_64_64": {"en":"He never turns back from doing right. Śrī (Lakṣmī) lives on His chest — He is her Lord and the best of all who are blessed.","te":"ధర్మం చేయడంలో ఆయన ఎన్నడూ వెనుకడుగు వేయడు. శ్రీ (లక్ష్మి) ఆయన వక్షస్థలంపై నివసిస్తుంది — ఆమెకు ప్రభువు ఆయనే, ధన్యులందరిలో శ్రేష్ఠుడు.","hi":"वे सही करने से कभी पीछे नहीं हटते। श्री (लक्ष्मी) उनके वक्ष पर बसती हैं — वे उनके स्वामी हैं और सब धन्य लोगों में श्रेष्ठ।"},
"vsn_65_65": {"en":"This whole verse is about Śrī — prosperity and grace. Every kind of blessing comes from Him, and He is the support of all three worlds.","te":"ఈ శ్లోకమంతా శ్రీ గురించే — ఐశ్వర్యం, అనుగ్రహం. ప్రతి రకమైన ఆశీస్సూ ఆయన నుండే వస్తుంది; మూడు లోకాలకూ ఆధారం ఆయనే.","hi":"यह पूरा श्लोक श्री के बारे में है — समृद्धि और कृपा। हर प्रकार का आशीर्वाद उन्हीं से आता है, और वे तीनों लोकों के आधार हैं।"},
"vsn_66_66": {"en":"Beautiful in every way and full of joy, He has mastered Himself and is ruled by no one. He clears away all our doubts.","te":"అన్ని విధాలా అందమైనవాడు, ఆనందంతో నిండినవాడు; తనను తాను జయించినవాడు, ఎవరికీ లొంగనివాడు. మన సందేహాలన్నిటినీ తొలగిస్తాడు.","hi":"हर तरह से सुंदर और आनंद से भरे, उन्होंने स्वयं को जीता है और किसी के अधीन नहीं। वे हमारे सब संशय दूर करते हैं।"},
"vsn_67_67": {"en":"He sees in every direction and has no master over Him. He is free from sorrow — and takes away the sorrow of those who come to Him.","te":"అన్ని దిక్కులనూ చూస్తాడు, ఆయనపై యజమాని లేడు. ఆయనకు శోకం లేదు — తన దగ్గరకు వచ్చినవారి శోకాన్ని పోగొడతాడు.","hi":"वे हर दिशा में देखते हैं और उनका कोई स्वामी नहीं। वे शोक से मुक्त हैं — और उनके पास आने वालों का शोक हर लेते हैं।"},
"vsn_68_68": {"en":"Shining and pure, He purifies everyone who remembers Him. No one can stop Him or match Him, and His strength has no limit.","te":"ప్రకాశించేవాడు, పవిత్రుడు; తనను స్మరించే ప్రతి ఒక్కరినీ పవిత్రం చేస్తాడు. ఆయనను ఎవరూ ఆపలేరు, సాటి రాలేరు; ఆయన బలానికి హద్దు లేదు.","hi":"दीप्त और पवित्र, वे उन्हें याद करने वाले हर व्यक्ति को पवित्र करते हैं। उन्हें कोई रोक नहीं सकता, कोई बराबरी नहीं कर सकता, और उनके बल की कोई सीमा नहीं।"},
"vsn_69_69": {"en":"He is Keśava and Hari, the Self and Lord of all three worlds. He defeated demons like Kālanemi and Keśī — He always protects the good.","te":"కేశవుడూ హరీ ఆయనే; మూడు లోకాలకూ ఆత్మ, ప్రభువు. కాలనేమి, కేశి వంటి రాక్షసులను ఓడించాడు — ఎప్పుడూ మంచివారిని కాపాడుతాడు.","hi":"वे केशव और हरि हैं, तीनों लोकों की आत्मा और स्वामी। उन्होंने कालनेमि और केशी जैसे असुरों को हराया — वे सदा अच्छों की रक्षा करते हैं।"},
"vsn_70_70": {"en":"He is the one all hearts truly long for, and He protects our good wishes. His form can't be put into words — endless, brave and all-pervading.","te":"అన్ని హృదయాలూ నిజంగా కోరుకునేది ఆయననే; మన మంచి కోరికలను ఆయన కాపాడుతాడు. ఆయన రూపాన్ని మాటల్లో చెప్పలేం — అనంతుడు, వీరుడు, సర్వవ్యాపి.","hi":"सब हृदय सचमुच उन्हीं की चाह रखते हैं, और वे हमारी अच्छी इच्छाओं की रक्षा करते हैं। उनका रूप शब्दों में नहीं आता — अनंत, वीर और सर्वव्यापी।"},
"vsn_71_71": {"en":"Every word of this verse plays on 'Brahma'. He is the Vedas, the knowledge of Brahman, and the infinite reality itself — and He loves those who seek that truth.","te":"ఈ శ్లోకంలో ప్రతి మాటా ‘బ్రహ్మ’ చుట్టూ తిరుగుతుంది. వేదాలూ, బ్రహ్మజ్ఞానమూ, అనంత సత్యమూ ఆయనే — ఆ సత్యాన్ని వెతికేవారిని ఆయన ప్రేమిస్తాడు.","hi":"इस श्लोक का हर शब्द 'ब्रह्म' से खेलता है। वे वेद हैं, ब्रह्म-ज्ञान हैं, और स्वयं अनंत सत्य — और उस सत्य को खोजने वालों से प्रेम करते हैं।"},
"vsn_72_72": {"en":"Everything about Him is great — His steps, His deeds, His brilliance. He is the greatest sacrifice and the one to whom every offering goes.","te":"ఆయనకు సంబంధించిన ప్రతిదీ గొప్పదే — ఆయన అడుగులు, కర్మలు, తేజస్సు. ఆయనే మహా యజ్ఞం; ప్రతి అర్పణా చేరేది ఆయనకే.","hi":"उनसे जुड़ी हर बात महान है — उनके पग, उनके कर्म, उनका तेज। वे सबसे बड़ा यज्ञ हैं और हर भेंट उन्हीं तक पहुँचती है।"},
"vsn_73_73": {"en":"He loves to be praised — not for Himself, but because praising Him lifts us up. He is complete, fills our lives, and His name is holy.","te":"ఆయన స్తుతిని ఇష్టపడతాడు — తన కోసం కాదు, ఆయనను స్తుతిస్తే మనమే ఉన్నతులమవుతాం కాబట్టి. ఆయన పరిపూర్ణుడు, మన జీవితాలను నింపుతాడు; ఆయన నామం పవిత్రం.","hi":"उन्हें स्तुति प्रिय है — अपने लिए नहीं, बल्कि इसलिए कि उनकी स्तुति हमें ऊपर उठाती है। वे पूर्ण हैं, हमारे जीवन को भरते हैं, और उनका नाम पवित्र है।"},
"vsn_74_74": {"en":"He is as fast as the mind — the moment we think of Him, He is there. He gives wealth and, best of all, freedom.","te":"ఆయన మనసంత వేగవంతుడు — మనం తలచుకున్న క్షణమే అక్కడ ఉంటాడు. సంపద ఇస్తాడు; అన్నిటికంటే గొప్పది — ముక్తిని ఇస్తాడు.","hi":"वे मन जितने तेज़ हैं — जैसे ही हम उन्हें याद करते हैं, वे वहाँ होते हैं। वे धन देते हैं, और सबसे बढ़कर, मुक्ति।"},
"vsn_75_75": {"en":"He is the goal of good people and their true home. Born in the Yadu family by the Yamunā river, He is goodness itself.","te":"మంచివారి గమ్యమూ, వారి నిజమైన నివాసమూ ఆయనే. యమునా తీరంలో యదువంశంలో పుట్టినవాడు; మంచితనమే ఆయన.","hi":"वे अच्छे लोगों का लक्ष्य और उनका सच्चा घर हैं। यमुना तट पर यदुकुल में जन्मे, वे स्वयं भलाई हैं।"},
"vsn_76_76": {"en":"Every being lives in Him. He humbles the proud but gives dignity to the good. Nothing can defeat Him.","te":"ప్రతి ప్రాణీ ఆయనలోనే నివసిస్తుంది. గర్వం ఉన్నవారిని తగ్గిస్తాడు, మంచివారికి గౌరవం ఇస్తాడు. ఆయనను ఏదీ ఓడించలేదు.","hi":"हर प्राणी उन्हीं में रहता है। वे अहंकारी को झुकाते हैं और अच्छे को सम्मान देते हैं। उन्हें कुछ भी हरा नहीं सकता।"},
"vsn_77_77": {"en":"The whole universe is His form, yet He has no fixed form. He appears in hundreds of ways — so wherever we look with love, we can find Him.","te":"విశ్వమంతా ఆయన రూపమే, అయినా ఆయనకు ఒక స్థిర రూపం లేదు. వందల విధాలుగా కనిపిస్తాడు — ప్రేమతో ఎక్కడ చూసినా ఆయనను కనుక్కోవచ్చు.","hi":"पूरा विश्व उनका रूप है, फिर भी उनका कोई निश्चित रूप नहीं। वे सैकड़ों तरह से प्रकट होते हैं — इसलिए जहाँ भी प्रेम से देखें, उन्हें पा सकते हैं।"},
"vsn_78_78": {"en":"He is One, yet appears as many. He is the 'That' the sages point to, the friend and Lord of the world — and He loves His devotees dearly (Bhaktavatsala).","te":"ఆయన ఒక్కడే, అయినా అనేకులుగా కనిపిస్తాడు. ఋషులు సూచించే ‘అది’ ఆయనే; లోకానికి బంధువూ ప్రభువూ — భక్తులను అమితంగా ప్రేమించేవాడు (భక్తవత్సలుడు).","hi":"वे एक हैं, फिर भी अनेक दिखते हैं। ऋषि जिस 'तत्' की ओर इशारा करते हैं वह वही हैं, संसार के मित्र और स्वामी — और भक्तों से अत्यंत प्रेम करने वाले (भक्तवत्सल)।"},
"vsn_79_79": {"en":"He glows like gold. He is beyond all labels, needs nothing from anyone, and is both perfectly still and always moving.","te":"బంగారం వలె మెరిసేవాడు. ఏ గుర్తింపులకూ అందనివాడు, ఎవరి నుండీ ఏమీ అవసరం లేనివాడు; పూర్తిగా నిశ్చలుడు, అయినా ఎప్పుడూ కదిలేవాడు.","hi":"वे सोने जैसे दमकते हैं। वे हर पहचान से परे हैं, किसी से कुछ नहीं चाहते, और पूर्ण स्थिर होकर भी सदा गतिशील हैं।"},
"vsn_80_80": {"en":"Though He is the greatest, He has no pride — and He gives respect to others. He is wise, truthful and holds up the whole earth.","te":"అందరికంటే గొప్పవాడైనా ఆయనకు గర్వం లేదు — ఇతరులకు గౌరవం ఇస్తాడు. జ్ఞాని, సత్యవంతుడు, భూమి అంతటినీ ధరించేవాడు.","hi":"सबसे महान होकर भी उन्हें अभिमान नहीं — वे दूसरों को सम्मान देते हैं। वे ज्ञानी, सत्यवादी हैं और पूरी पृथ्वी को थामे हैं।"},
"vsn_81_81": {"en":"He is full of brilliance and is the best of all warriors. He accepts our offerings with love and keeps everything in check.","te":"తేజస్సుతో నిండినవాడు, యోధులందరిలో శ్రేష్ఠుడు. మన అర్పణలను ప్రేమతో స్వీకరిస్తాడు, అన్నిటినీ అదుపులో ఉంచుతాడు.","hi":"वे तेज से भरे हैं और सब योद्धाओं में श्रेष्ठ। वे हमारी भेंट प्रेम से स्वीकारते हैं और सबको नियंत्रण में रखते हैं।"},
"vsn_82_82": {"en":"Four arms, four forms, four Vedas — He holds every part of life together. And yet, all this vast universe is only a small part of Him.","te":"నాలుగు భుజాలు, నాలుగు రూపాలు, నాలుగు వేదాలు — జీవితంలోని ప్రతి భాగాన్నీ ఆయనే కలిపి ఉంచుతాడు. అయినా ఈ విశాల విశ్వమంతా ఆయనలో ఒక చిన్న భాగం మాత్రమే.","hi":"चार भुजाएँ, चार रूप, चार वेद — वे जीवन के हर हिस्से को जोड़े रखते हैं। फिर भी यह विशाल विश्व उनका एक छोटा-सा अंश ही है।"},
"vsn_83_83": {"en":"He is not easy to win over with pride or cleverness — only sincere devotion reaches Him. To the wicked He is unreachable; to the loving, He comes running.","te":"గర్వంతో, తెలివితో ఆయనను పొందడం సులభం కాదు — నిజమైన భక్తి మాత్రమే ఆయనను చేరుతుంది. దుష్టులకు అందనివాడు; ప్రేమించేవారి దగ్గరకు పరుగెత్తుకుంటూ వస్తాడు.","hi":"अहंकार या चतुराई से उन्हें पाना आसान नहीं — केवल सच्ची भक्ति उन तक पहुँचती है। दुष्टों के लिए वे अगम्य हैं; प्रेम करने वालों के पास दौड़े चले आते हैं।"},
"vsn_84_84": {"en":"Like a thread holding together a garland of flowers, He holds the whole world together. His deeds are great, and He has given us the scriptures.","te":"పూలమాలను దారం కలిపి ఉంచినట్టు, ప్రపంచమంతటినీ ఆయనే కలిపి ఉంచుతాడు. ఆయన కర్మలు గొప్పవి; మనకు శాస్త్రాలను ఇచ్చినవాడు ఆయనే.","hi":"जैसे धागा फूलों की माला को जोड़े रखता है, वैसे ही वे पूरे संसार को जोड़े रखते हैं। उनके कर्म महान हैं, और उन्होंने हमें शास्त्र दिए।"},
"vsn_85_85": {"en":"He is beautiful and kind-hearted, with lovely eyes. He feeds the world, knows everything, and always wins.","te":"అందమైనవాడు, దయగల హృదయం గలవాడు, చక్కని కన్నులవాడు. లోకానికి అన్నం పెడతాడు, అన్నీ తెలిసినవాడు, ఎప్పుడూ గెలుస్తాడు.","hi":"वे सुंदर और दयालु हैं, प्यारी आँखों वाले। वे संसार को भोजन देते हैं, सब जानते हैं, और सदा जीतते हैं।"},
"vsn_86_86": {"en":"He is like a vast, deep lake of peace that can never be disturbed. All the greatest treasures are in Him.","te":"ఆయన ఎన్నటికీ కలత చెందని విశాలమైన, లోతైన శాంతి సరస్సు వంటివాడు. గొప్ప నిధులన్నీ ఆయనలోనే ఉన్నాయి.","hi":"वे शांति की उस विशाल, गहरी झील जैसे हैं जो कभी विचलित नहीं होती। सब महान ख़ज़ाने उन्हीं में हैं।"},
"vsn_87_87": {"en":"Like rain that cools a hot summer, He soothes our suffering. He is pure as a jasmine flower, never dies, and faces every direction at once.","te":"వేసవి వేడిని చల్లార్చే వాన లాగా ఆయన మన బాధను ఉపశమింపజేస్తాడు. మల్లెపువ్వంత నిర్మలుడు, మరణం లేనివాడు, ఒకేసారి అన్ని దిక్కులకూ ముఖం గలవాడు.","hi":"गर्मी को ठंडा करने वाली बारिश की तरह वे हमारे दुःख को शांत करते हैं। वे कुंद-पुष्प जैसे निर्मल, अमर, और एक साथ हर दिशा में मुख वाले हैं।"},
"vsn_88_88": {"en":"He is easy to reach for anyone who simply loves Him (Sulabha). Like the great banyan tree, He shelters everyone beneath Him.","te":"ఆయనను కేవలం ప్రేమించేవారికి ఆయన సులభంగా దొరుకుతాడు (సులభుడు). మహా మర్రిచెట్టులా అందరికీ తన కింద నీడనిస్తాడు.","hi":"जो उनसे बस प्रेम करता है, उसके लिए वे सहज सुलभ हैं (सुलभ)। विशाल बरगद की तरह वे सबको अपनी छाँव देते हैं।"},
"vsn_89_89": {"en":"He is the fire with seven flames and the sun with seven horses. Beyond thought and without fault, He makes evil afraid — and takes away the fear of the good.","te":"ఏడు జ్వాలల అగ్నీ, ఏడు గుర్రాల సూర్యుడూ ఆయనే. ఆలోచనకు అందనివాడు, దోషం లేనివాడు; చెడును భయపెడతాడు — మంచివారి భయాన్ని పోగొడతాడు.","hi":"वे सात ज्वालाओं वाली अग्नि और सात घोड़ों वाले सूर्य हैं। विचार से परे और निर्दोष, वे बुराई को डराते हैं — और अच्छों का भय हरते हैं।"},
"vsn_90_90": {"en":"He is smaller than an atom and bigger than the universe. He has qualities we can love, yet is beyond all qualities. He keeps families and lineages going.","te":"అణువు కంటే చిన్నవాడు, విశ్వం కంటే పెద్దవాడు. మనం ప్రేమించగలిగే గుణాలు గలవాడు, అయినా గుణాలకు అతీతుడు. వంశాలను కొనసాగిస్తాడు.","hi":"वे परमाणु से छोटे और विश्व से बड़े हैं। उनमें प्रेम करने योग्य गुण हैं, फिर भी वे गुणों से परे हैं। वे परिवारों और वंशों को आगे बढ़ाते हैं।"},
"vsn_91_91": {"en":"He carries the world's burden and is the master of yogīs. He fulfils every good wish and is the resting place for anyone weary of life.","te":"లోక భారాన్ని మోసేవాడు, యోగులకు గురువు. ప్రతి మంచి కోరికనూ తీరుస్తాడు; జీవితంలో అలసిపోయిన ఎవరికైనా విశ్రాంతి స్థానం ఆయనే.","hi":"वे संसार का भार उठाते हैं और योगियों के स्वामी हैं। वे हर अच्छी इच्छा पूरी करते हैं और जीवन से थके हर व्यक्ति का विश्राम-स्थल हैं।"},
"vsn_92_92": {"en":"As Rāma, He was the perfect archer. He disciplines wrongdoing like a fair judge, bears everything patiently, and is never defeated.","te":"శ్రీరామునిగా సాటిలేని ధనుర్ధారి. న్యాయమూర్తిలా తప్పులను శిక్షిస్తాడు, అన్నిటినీ ఓర్పుతో భరిస్తాడు, ఎన్నడూ ఓడడు.","hi":"राम रूप में वे अद्वितीय धनुर्धर थे। वे न्यायी न्यायाधीश की तरह गलती का दंड देते हैं, सब धैर्य से सहते हैं, और कभी हारते नहीं।"},
"vsn_93_93": {"en":"He is goodness and truth, devoted to what is right. Worthy of our love, He does what is dear to us and makes our love grow.","te":"మంచితనమూ సత్యమూ ఆయనే; ధర్మానికి అంకితుడు. మన ప్రేమకు అర్హుడు; మనకు ప్రియమైనది చేస్తాడు, మన ప్రేమను పెంచుతాడు.","hi":"वे भलाई और सत्य हैं, धर्म में निष्ठ। वे हमारे प्रेम के योग्य हैं, हमारा प्रिय करते हैं और हमारा प्रेम बढ़ाते हैं।"},
"vsn_94_94": {"en":"He moves across the sky as the sun, the light that gives life. The sun itself is His eye — through it He watches over the whole world.","te":"సూర్యునిగా ఆకాశంలో సంచరిస్తాడు — ప్రాణం ఇచ్చే వెలుగు ఆయనే. సూర్యుడే ఆయన కన్ను — దాని ద్వారా ప్రపంచమంతటినీ గమనిస్తాడు.","hi":"वे सूर्य बनकर आकाश में चलते हैं, जीवन देने वाला प्रकाश। सूर्य ही उनका नेत्र है — उसी से वे पूरे संसार पर नज़र रखते हैं।"},
"vsn_95_95": {"en":"Endless and full of wonder, He gives happiness and never gets tired of forgiving us. The whole world rests on Him.","te":"అనంతుడు, అద్భుతాలతో నిండినవాడు; ఆనందం ఇస్తాడు, మనల్ని క్షమించడంలో ఎన్నడూ అలసిపోడు. ప్రపంచమంతా ఆయనపైనే ఆధారపడింది.","hi":"अनंत और अद्भुत, वे सुख देते हैं और हमें क्षमा करते-करते कभी नहीं थकते। पूरा संसार उन्हीं पर टिका है।"},
"vsn_96_96": {"en":"He is the most ancient one. This verse repeats 'svasti' — well-being — again and again: He gives it, makes it, is it, and loves to share it.","te":"ఆయన అత్యంత సనాతనుడు. ఈ శ్లోకం ‘స్వస్తి’ — క్షేమం — అనే మాటను మళ్ళీ మళ్ళీ చెబుతుంది: క్షేమాన్ని ఇచ్చేదీ, చేసేదీ, క్షేమమే తానైనదీ, దాన్ని పంచుకోవడానికి ఇష్టపడేదీ ఆయనే.","hi":"वे सबसे प्राचीन हैं। यह श्लोक 'स्वस्ति' — कल्याण — बार-बार दोहराता है: वे उसे देते हैं, करते हैं, स्वयं वही हैं, और उसे बाँटना पसंद करते हैं।"},
"vsn_97_97": {"en":"He is never harsh. With His discus and earrings He rules with strength, yet He is cool and gentle, beyond anything words can capture.","te":"ఆయన ఎన్నడూ కఠినంగా ఉండడు. చక్రం, కుండలాలతో బలంగా పాలిస్తాడు; అయినా చల్లగా, సౌమ్యంగా ఉంటాడు — మాటలకు అందనివాడు.","hi":"वे कभी कठोर नहीं। चक्र और कुंडलों के साथ वे बल से शासन करते हैं, फिर भी शीतल और सौम्य हैं, शब्दों की पकड़ से परे।"},
"vsn_98_98": {"en":"He is never cruel, always graceful and generous, and the most forgiving of all. Just hearing or singing His name is a blessing.","te":"ఆయన ఎన్నడూ క్రూరుడు కాడు; ఎప్పుడూ మనోహరుడు, ఉదారుడు, అందరికంటే ఎక్కువ క్షమించేవాడు. ఆయన నామాన్ని వినడమే, పాడడమే ఒక ఆశీర్వాదం.","hi":"वे कभी क्रूर नहीं, सदा मनोहर और उदार, और सबसे अधिक क्षमाशील। उनका नाम सुनना या गाना ही आशीर्वाद है।"},
"vsn_99_99": {"en":"He lifts us across the ocean of worries, destroys our wrong deeds and even chases away bad dreams. He protects us and keeps us alive.","te":"ఆందోళనల సముద్రాన్ని దాటిస్తాడు, మన తప్పు పనుల ఫలాన్ని నశింపజేస్తాడు, చెడు కలలను కూడా తరిమేస్తాడు. మనల్ని రక్షించి, బ్రతికిస్తాడు.","hi":"वे चिंताओं के सागर से पार कराते हैं, हमारे गलत कर्मों को नष्ट करते हैं और बुरे सपनों को भी भगाते हैं। वे हमारी रक्षा करते हैं और हमें जीवित रखते हैं।"},
"vsn_100_100": {"en":"His forms and riches are endless. He has conquered anger, removes fear, and is perfectly fair — giving everyone exactly what is right.","te":"ఆయన రూపాలూ సంపదలూ అనంతం. కోపాన్ని జయించినవాడు, భయాన్ని పోగొట్టేవాడు, పూర్తిగా న్యాయవంతుడు — ప్రతి ఒక్కరికీ సరిగ్గా తగినది ఇస్తాడు.","hi":"उनके रूप और ऐश्वर्य अनंत हैं। उन्होंने क्रोध जीता है, भय हरते हैं, और पूर्ण न्यायी हैं — हर किसी को ठीक वही देते हैं जो उचित है।"},
"vsn_101_101": {"en":"He has no beginning. He is the earth's beauty and support, the brave hero, and the one from whom every birth begins.","te":"ఆయనకు ఆది లేదు. భూమికి అందమూ ఆధారమూ ఆయనే, ధైర్యశాలి, ప్రతి జన్మా మొదలయ్యేది ఆయన నుండే.","hi":"उनका कोई आदि नहीं। वे पृथ्वी की सुंदरता और आधार हैं, वीर नायक, और हर जन्म उन्हीं से शुरू होता है।"},
"vsn_102_102": {"en":"He supports everything but needs no support. His smile is like a blossoming flower. Ever awake, He walks the path of the good and is the sacred Om.","te":"అన్నిటికీ ఆధారం ఆయనే, ఆయనకు మాత్రం ఆధారం అక్కర్లేదు. వికసించిన పువ్వు వంటి చిరునవ్వు ఆయనది. ఎప్పుడూ మేల్కొని, సన్మార్గంలో నడుస్తాడు; పవిత్ర ఓంకారం ఆయనే.","hi":"वे सबके आधार हैं, पर उन्हें किसी आधार की ज़रूरत नहीं। उनकी मुस्कान खिले फूल जैसी है। सदा जाग्रत, वे सत्पथ पर चलते हैं और पवित्र ॐ हैं।"},
"vsn_103_103": {"en":"He is the truth behind everything and the One Self in all. Our breath and life rest in Him, and He is beyond birth, death and old age.","te":"అన్నిటి వెనుక ఉన్న సత్యం ఆయనే, అందరిలో ఉన్న ఏకైక ఆత్మ. మన శ్వాసా జీవితమూ ఆయనలోనే ఉన్నాయి; జనన మరణ వృద్ధాప్యాలకు అతీతుడు.","hi":"वे हर चीज़ के पीछे का सत्य और सबमें एक आत्मा हैं। हमारी साँस और जीवन उन्हीं में हैं, और वे जन्म, मृत्यु और बुढ़ापे से परे हैं।"},
"vsn_104_104": {"en":"He is the great tree whose branches are the three worlds, and the father even of the creator. Every sacred offering is Him and goes to Him.","te":"మూడు లోకాలే కొమ్మలుగా గల మహా వృక్షం ఆయనే; సృష్టికర్తకు కూడా తండ్రి. ప్రతి పవిత్ర అర్పణా ఆయనే, ఆయనకే చేరుతుంది.","hi":"वे वह महान वृक्ष हैं जिसकी शाखाएँ तीनों लोक हैं, और सृष्टिकर्ता के भी पिता। हर पवित्र भेंट वही हैं और उन्हीं तक जाती है।"},
"vsn_105_105": {"en":"From start to finish, every sacred act is Him. He is the food that nourishes us — and also the one who receives it within us.","te":"మొదటి నుండి చివరి వరకు ప్రతి పవిత్ర కర్మా ఆయనే. మనల్ని పోషించే అన్నమూ ఆయనే — మనలో దాన్ని స్వీకరించేవాడూ ఆయనే.","hi":"शुरू से अंत तक हर पवित्र कर्म वही हैं। हमें पोषण देने वाला अन्न भी वही हैं — और हमारे भीतर उसे ग्रहण करने वाले भी।"},
"vsn_106_106": {"en":"No one created Him — He came from Himself. He is Devakī's beloved son Kṛṣṇa, the Lord of the earth, who washes away our sins.","te":"ఆయనను ఎవరూ సృష్టించలేదు — తనంతట తానే వచ్చాడు. దేవకీదేవికి ప్రియమైన కుమారుడు శ్రీకృష్ణుడు, భూమికి ప్రభువు, మన పాపాలను కడిగేవాడు.","hi":"उन्हें किसी ने नहीं बनाया — वे स्वयं से प्रकट हुए। वे देवकी के प्रिय पुत्र श्रीकृष्ण हैं, पृथ्वी के स्वामी, जो हमारे पाप धो देते हैं।"},
"vsn_107_107": {"en":"Conch, sword, discus, bow, mace — He holds every weapon, not to harm, but to protect. Nothing can shake Him.","te":"శంఖం, ఖడ్గం, చక్రం, ధనుస్సు, గద — అన్ని ఆయుధాలూ ఆయన చేతిలో ఉన్నాయి — హాని చేయడానికి కాదు, కాపాడడానికి. ఆయనను ఏదీ కదిలించలేదు.","hi":"शंख, खड्ग, चक्र, धनुष, गदा — वे हर आयुध धारण करते हैं, हानि के लिए नहीं, रक्षा के लिए। उन्हें कुछ भी डिगा नहीं सकता।"},
"vsn_108_108": {"en":"The thousand names end with a simple prayer: may the Lord, fully armed to protect us and wearing His forest garland, keep us safe. After all the names, what we really ask for is His protection.","te":"వేయి నామాలు ఒక సరళమైన ప్రార్థనతో ముగుస్తాయి: మనల్ని కాపాడడానికి అన్ని ఆయుధాలూ ధరించి, వనమాలతో ఉన్న ప్రభువు మనల్ని రక్షించుగాక. అన్ని నామాల తర్వాత మనం నిజంగా కోరేది ఆయన రక్షణనే.","hi":"सहस्र नाम एक सरल प्रार्थना से समाप्त होते हैं: हमारी रक्षा के लिए सब आयुध धारण किए, वनमाला पहने प्रभु हमें सुरक्षित रखें। सब नामों के बाद हम सच में उनकी रक्षा ही माँगते हैं।"},
"vsn_phala_1": {"en":"The thousand names are complete. Now Bhīṣma tells us what good comes from chanting them — this closing part is called the Phalaśruti, 'hearing the fruits'.","te":"వేయి నామాలు పూర్తయ్యాయి. వాటిని పఠిస్తే కలిగే మేలును ఇప్పుడు భీష్ముడు చెబుతున్నాడు — ఈ చివరి భాగాన్నే ఫలశ్రుతి — ‘ఫలాలను వినడం’ — అంటారు.","hi":"सहस्र नाम पूरे हुए। अब भीष्म बताते हैं कि इनके पाठ से क्या भला होता है — इस अंतिम भाग को फलश्रुति, 'फलों का श्रवण', कहते हैं।"},
"vsn_phala_2": {"en":"Even just listening every day protects us. You don't have to be an expert — hearing these names with an open heart is enough.","te":"ప్రతిరోజూ వినడమే మనల్ని కాపాడుతుంది. మీరు నిపుణులు కానక్కరలేదు — తెరిచిన మనసుతో ఈ నామాలను వినడమే చాలు.","hi":"प्रतिदिन केवल सुनना भी हमारी रक्षा करता है। विशेषज्ञ होने की ज़रूरत नहीं — खुले मन से इन नामों को सुनना काफ़ी है।"},
"vsn_phala_3": {"en":"Whatever your role in life — scholar, leader, business person or worker — chanting helps you succeed in your own field. God supports every honest path.","te":"జీవితంలో మీ పాత్ర ఏదైనా — పండితుడు, నాయకుడు, వ్యాపారి, శ్రామికుడు — పఠనం మీ రంగంలో విజయానికి సహాయపడుతుంది. ప్రతి నిజాయితీ మార్గానికీ దేవుడు తోడుంటాడు.","hi":"जीवन में आपकी भूमिका जो भी हो — विद्वान, नेता, व्यापारी या मेहनतकश — पाठ आपको अपने क्षेत्र में सफल होने में मदद करता है। भगवान हर ईमानदार राह का साथ देते हैं।"},
"vsn_phala_4": {"en":"Whatever good thing you sincerely seek — to live rightly, to earn well, to be happy, to have children — it comes to you.","te":"మీరు నిజాయితీగా కోరే మంచిదేదైనా — ధర్మంగా జీవించడం, బాగా సంపాదించడం, సంతోషంగా ఉండడం, సంతానం — అది మీకు లభిస్తుంది.","hi":"आप जो भी अच्छी चीज़ सच्चे मन से चाहें — धर्म से जीना, अच्छा कमाना, खुश रहना, संतान — वह आपको मिलती है।"},
"vsn_phala_5": {"en":"The best way to chant: wake up early, freshen up, and give it your full attention. A few quiet morning minutes with a focused mind make a big difference.","te":"పఠించడానికి ఉత్తమ మార్గం: తెల్లవారుజామునే లేచి, శుచిగా అయి, పూర్తి శ్రద్ధతో చేయడం. ఏకాగ్రమైన మనసుతో ఉదయాన్నే కొన్ని ప్రశాంత నిమిషాలు చాలా మార్పు తెస్తాయి.","hi":"पाठ का सबसे अच्छा तरीका: सुबह जल्दी उठें, नहा-धोकर पूरे ध्यान से करें। एकाग्र मन से सुबह के कुछ शांत मिनट बड़ा अंतर लाते हैं।"},
"vsn_phala_6": {"en":"Such a person earns good name and respect, lasting prosperity, and above all, the highest good — peace and closeness to God.","te":"అలాంటి వ్యక్తికి మంచి పేరు, గౌరవం, స్థిరమైన సంపద — అన్నిటికంటే మించి అత్యున్నత శ్రేయస్సు — శాంతి, దేవునికి దగ్గరితనం — లభిస్తాయి.","hi":"ऐसे व्यक्ति को अच्छा नाम, सम्मान, स्थायी समृद्धि, और सबसे बढ़कर सर्वोच्च कल्याण — शांति और भगवान से निकटता — मिलती है।"},
"vsn_phala_7": {"en":"Fear goes away, courage and good health come. Regular chanting builds an inner strength that shows on the outside too.","te":"భయం పోతుంది, ధైర్యం, ఆరోగ్యం వస్తాయి. రోజూ పఠిస్తే లోపల ఏర్పడే బలం బయట కూడా కనిపిస్తుంది.","hi":"भय दूर होता है, साहस और अच्छा स्वास्थ्य आता है। नियमित पाठ भीतर ऐसी शक्ति बनाता है जो बाहर भी दिखती है।"},
"vsn_phala_8": {"en":"These names are a source of hope in hard times — for the sick, the trapped, the frightened and the troubled. Many families chant them especially in difficult days.","te":"కష్టకాలంలో ఈ నామాలు ఆశకు ఆధారం — రోగులకు, చిక్కుల్లో ఉన్నవారికి, భయపడినవారికి, ఆపదలో ఉన్నవారికి. చాలా కుటుంబాలు కష్ట దినాల్లో వీటిని ప్రత్యేకంగా పఠిస్తాయి.","hi":"कठिन समय में ये नाम आशा का स्रोत हैं — बीमार, फँसे हुए, डरे हुए और परेशान लोगों के लिए। बहुत से परिवार मुश्किल दिनों में इन्हें विशेष रूप से पढ़ते हैं।"},
"vsn_phala_9": {"en":"Life's obstacles are crossed quickly by one who praises God every day with love. Daily practice is the key.","te":"ప్రతిరోజూ ప్రేమతో దేవుణ్ణి స్తుతించేవాడు జీవితంలోని అడ్డంకులను త్వరగా దాటుతాడు. రోజువారీ అభ్యాసమే ముఖ్యం.","hi":"जो प्रतिदिन प्रेम से भगवान की स्तुति करता है, वह जीवन की बाधाएँ जल्दी पार करता है। रोज़ का अभ्यास ही कुंजी है।"},
"vsn_phala_10": {"en":"When we make God our support, our mistakes are washed away and we reach the eternal. Taking refuge in Him is itself the cleansing.","te":"దేవుణ్ణే ఆధారంగా చేసుకుంటే మన తప్పులు కడిగివేయబడతాయి, శాశ్వతమైనదాన్ని చేరుకుంటాం. ఆయనను ఆశ్రయించడమే శుద్ధి.","hi":"जब हम भगवान को अपना सहारा बनाते हैं, हमारी गलतियाँ धुल जाती हैं और हम शाश्वत तक पहुँचते हैं। उनकी शरण लेना ही शुद्धि है।"},
"vsn_phala_11": {"en":"For His devotees, the big fears of life — birth, death, ageing and illness — lose their grip. Faith gives a deep sense of safety.","te":"ఆయన భక్తులకు జీవితంలోని పెద్ద భయాలు — జననం, మరణం, వృద్ధాప్యం, రోగం — పట్టు కోల్పోతాయి. నమ్మకం లోతైన భద్రతా భావాన్ని ఇస్తుంది.","hi":"उनके भक्तों के लिए जीवन के बड़े भय — जन्म, मृत्यु, बुढ़ापा और रोग — अपनी पकड़ खो देते हैं। आस्था सुरक्षा का गहरा भाव देती है।"},
"vsn_phala_12": {"en":"With faith and devotion, this hymn brings inner happiness, patience, courage, a sharp memory and a good name. The key words are 'faith' and 'devotion'.","te":"శ్రద్ధాభక్తులతో పఠిస్తే ఈ స్తోత్రం అంతరంగ ఆనందాన్ని, ఓర్పును, ధైర్యాన్ని, మంచి జ్ఞాపకశక్తిని, మంచి పేరును ఇస్తుంది. ముఖ్యమైన మాటలు ‘శ్రద్ధ’, ‘భక్తి’.","hi":"श्रद्धा और भक्ति से यह स्तोत्र भीतरी सुख, धैर्य, साहस, तेज़ स्मृति और अच्छा नाम देता है। मुख्य शब्द हैं 'श्रद्धा' और 'भक्ति'।"},
"vsn_phala_13": {"en":"The real sign of a devotee isn't outward show — it's an inner change: less anger, less jealousy, less greed, cleaner thoughts.","te":"భక్తుని నిజమైన గుర్తు బయటి ఆడంబరం కాదు — లోపలి మార్పు: తక్కువ కోపం, తక్కువ అసూయ, తక్కువ లోభం, శుభ్రమైన ఆలోచనలు.","hi":"भक्त की सच्ची पहचान बाहरी दिखावा नहीं — भीतरी बदलाव है: कम क्रोध, कम ईर्ष्या, कम लोभ, साफ़ विचार।"},
"vsn_phala_14": {"en":"Look up at the sky, the sun, moon and stars, the earth and the ocean — they all stay in place by His power. The same God holds us too.","te":"ఆకాశాన్ని, సూర్యచంద్ర నక్షత్రాలను, భూమిని, సముద్రాన్ని చూడండి — అవన్నీ ఆయన శక్తితోనే నిలిచి ఉన్నాయి. అదే దేవుడు మనల్నీ పట్టుకుని ఉన్నాడు.","hi":"आकाश, सूर्य, चंद्र, तारे, पृथ्वी और समुद्र को देखिए — सब उनकी शक्ति से टिके हैं। वही भगवान हमें भी थामे हुए हैं।"},
"vsn_phala_15": {"en":"Gods and demons, humans and animals — every living thing, good or bad, is under Kṛṣṇa's care and control. Nothing is outside Him.","te":"దేవతలూ రాక్షసులూ, మనుషులూ జంతువులూ — మంచైనా చెడైనా ప్రతి జీవీ శ్రీకృష్ణుని సంరక్షణలో, ఆధీనంలో ఉంది. ఆయనకు బయట ఏదీ లేదు.","hi":"देवता और असुर, मनुष्य और पशु — हर जीव, अच्छा या बुरा, श्रीकृष्ण की देखरेख और नियंत्रण में है। कुछ भी उनसे बाहर नहीं।"},
"vsn_phala_16": {"en":"Our senses, mind, intelligence, energy and courage — even our body and the soul inside it — are all expressions of God. He is closer than we think.","te":"మన ఇంద్రియాలు, మనసు, బుద్ధి, శక్తి, ధైర్యం — మన శరీరం, దానిలోని ఆత్మ కూడా — అన్నీ దేవుని వ్యక్తీకరణలే. మనం అనుకున్నదానికంటే ఆయన దగ్గరగా ఉన్నాడు.","hi":"हमारी इंद्रियाँ, मन, बुद्धि, ऊर्जा और साहस — हमारा शरीर और उसमें बसी आत्मा भी — सब भगवान की ही अभिव्यक्ति हैं। वे हमारी सोच से भी पास हैं।"},
"vsn_phala_17": {"en":"Good conduct comes first; from it comes dharma, and the Lord of dharma is God. In other words: live well, and you are already walking towards Him.","te":"మంచి నడవడికే మొదటి స్థానం; దాని నుండే ధర్మం పుడుతుంది; ఆ ధర్మానికి ప్రభువు దేవుడు. అంటే: మంచిగా జీవిస్తే మీరు ఇప్పటికే ఆయన వైపు నడుస్తున్నారు.","hi":"अच्छा आचरण सबसे पहले है; उसी से धर्म आता है, और धर्म के स्वामी भगवान हैं। यानी: अच्छे से जियो, तो तुम पहले से उनकी ओर चल रहे हो।"},
"vsn_phala_18": {"en":"The sages, the ancestors, the gods, nature and the elements — everything we see came from Nārāyaṇa. We are all one big family with one source.","te":"ఋషులు, పితృదేవతలు, దేవతలు, ప్రకృతి, పంచభూతాలు — మనం చూసే ప్రతిదీ నారాయణుని నుండే వచ్చింది. మనమందరం ఒకే మూలం గల పెద్ద కుటుంబం.","hi":"ऋषि, पितर, देवता, प्रकृति और तत्व — जो कुछ हम देखते हैं, सब नारायण से आया। हम सब एक ही मूल वाला बड़ा परिवार हैं।"},
"vsn_phala_19": {"en":"All knowledge and all skills — yoga, philosophy, art, crafts, science, the Vedas — come from God. Every talent we have is His gift.","te":"అన్ని విద్యలూ, నైపుణ్యాలూ — యోగం, తత్త్వశాస్త్రం, కళలు, చేతిపనులు, విజ్ఞానం, వేదాలు — దేవుని నుండే వస్తాయి. మనలోని ప్రతి ప్రతిభా ఆయన కానుకే.","hi":"सारा ज्ञान और सारे कौशल — योग, दर्शन, कला, शिल्प, विज्ञान, वेद — भगवान से आते हैं। हमारी हर प्रतिभा उनका उपहार है।"},
"vsn_phala_20": {"en":"There is only one God, but He appears as countless different beings — like one sun reflected in many pots of water. He fills all three worlds.","te":"దేవుడు ఒక్కడే, కానీ లెక్కలేనన్ని వేర్వేరు జీవులుగా కనిపిస్తాడు — ఒకే సూర్యుడు అనేక నీటి కుండలలో ప్రతిబింబించినట్టు. మూడు లోకాలనూ నింపుతాడు.","hi":"भगवान एक ही हैं, पर अनगिनत अलग-अलग प्राणियों के रूप में दिखते हैं — जैसे एक सूर्य पानी के अनेक घड़ों में झलकता है। वे तीनों लोकों में भरे हैं।"},
"vsn_phala_21": {"en":"So, if you want a good and happy life, recite this hymn. That's Bhīṣma's simple advice to all of us.","te":"కాబట్టి మంచి, సంతోషకరమైన జీవితం కావాలంటే ఈ స్తోత్రాన్ని పఠించండి. మనందరికీ భీష్ముడు ఇచ్చే సరళమైన సలహా ఇదే.","hi":"तो, अगर आप अच्छा और सुखी जीवन चाहते हैं, यह स्तोत्र पढ़िए। हम सबको भीष्म की यही सरल सलाह है।"},
"vsn_phala_22": {"en":"Those who worship God never truly lose. Even when life knocks them down, they don't stay defeated.","te":"దేవుణ్ణి పూజించేవారు నిజంగా ఎన్నడూ ఓడిపోరు. జీవితం కింద పడేసినా, ఓటమిలో ఉండిపోరు.","hi":"भगवान की पूजा करने वाले कभी सचमुच नहीं हारते। जीवन गिरा भी दे, तो वे हार में पड़े नहीं रहते।"},
"vsn_phala_23": {"en":"Now Arjuna speaks, praying simply: Lord, please protect those who love You. It's the prayer of every devotee.","te":"ఇప్పుడు అర్జునుడు సరళంగా ప్రార్థిస్తున్నాడు: ప్రభూ, నిన్ను ప్రేమించేవారిని కాపాడు. ఇది ప్రతి భక్తుని ప్రార్థన.","hi":"अब अर्जुन सरल प्रार्थना करते हैं: प्रभु, जो आपसे प्रेम करते हैं उनकी रक्षा कीजिए। यह हर भक्त की प्रार्थना है।"},
"vsn_phala_24": {"en":"Kṛṣṇa's loving reply: even one verse, chanted sincerely, pleases Me as much as all thousand names. If you only have time for one, that's enough — it's the love that counts.","te":"శ్రీకృష్ణుని ప్రేమగల జవాబు: నిజాయితీగా పఠించిన ఒక్క శ్లోకం కూడా వేయి నామాలంత నన్ను సంతోషపెడుతుంది. ఒక్కదానికే సమయం ఉంటే అది చాలు — ముఖ్యమైనది ప్రేమ.","hi":"श्रीकृष्ण का प्रेमभरा उत्तर: सच्चे मन से पढ़ा एक श्लोक भी मुझे उतना ही प्रसन्न करता है जितने सहस्र नाम। अगर एक के लिए ही समय हो, तो वही काफ़ी है — प्रेम ही मायने रखता है।"},
"vsn_phala_25": {"en":"Vyāsa bows: the whole world is filled with Vāsudeva, and He lives in every being. So when we respect others, we are honouring Him.","te":"వ్యాసుడు నమస్కరిస్తున్నాడు: ప్రపంచమంతా వాసుదేవునితో నిండి ఉంది; ప్రతి ప్రాణిలో ఆయన నివసిస్తాడు. కాబట్టి ఇతరులను గౌరవిస్తే ఆయనను గౌరవించినట్టే.","hi":"व्यास नमन करते हैं: पूरा संसार वासुदेव से भरा है, और वे हर प्राणी में रहते हैं। इसलिए जब हम दूसरों का सम्मान करते हैं, तो उन्हीं का सम्मान करते हैं।"},
"vsn_phala_26": {"en":"Pārvatī asks Śiva a very practical question for busy people: is there a short way to get the blessing of all thousand names every day?","te":"బిజీగా ఉండేవారి కోసం పార్వతీదేవి శివుణ్ణి ఒక ఆచరణాత్మక ప్రశ్న అడుగుతోంది: వేయి నామాల ఫలాన్ని ప్రతిరోజూ పొందడానికి ఏదైనా చిన్న మార్గం ఉందా?","hi":"व्यस्त लोगों के लिए पार्वती शिव से एक व्यावहारिक प्रश्न पूछती हैं: क्या प्रतिदिन सहस्र नामों का फल पाने का कोई छोटा उपाय है?"},
"vsn_phala_27": {"en":"Śiva's answer: chant 'Śrī Rāma Rāma Rāma' — the name of Rāma is equal to all thousand names. That is why this verse is chanted three times: three 'Rāma's, and it holds the whole Sahasranāma.","te":"శివుని జవాబు: ‘శ్రీరామ రామ రామ’ అని జపించండి — రామ నామం వేయి నామాలకు సమానం. అందుకే ఈ శ్లోకాన్ని మూడుసార్లు పఠిస్తారు: మూడు ‘రామ’లలో సహస్రనామమంతా ఉంది.","hi":"शिव का उत्तर: 'श्रीराम राम राम' जपो — राम-नाम सहस्र नामों के बराबर है। इसीलिए यह श्लोक तीन बार पढ़ा जाता है: तीन 'राम' में पूरा सहस्रनाम समाया है।"},
"vsn_phala_28": {"en":"Brahmā, the creator, bows to the Infinite One with countless forms and names, who holds up endless ages. Even the creator bows to Him.","te":"సృష్టికర్త బ్రహ్మ కూడా లెక్కలేనన్ని రూపాలు, నామాలు గల, అంతులేని యుగాలను ధరించే అనంతునికి నమస్కరిస్తున్నాడు.","hi":"सृष्टिकर्ता ब्रह्मा भी अनगिनत रूपों और नामों वाले, अनंत युगों को थामने वाले अनंत को नमन करते हैं।"},
"vsn_phala_29": {"en":"The famous last line of the Gītā: where Kṛṣṇa and Arjuna are together — God's guidance and our honest effort — there success and goodness are certain.","te":"గీతలోని ప్రసిద్ధమైన చివరి శ్లోకం: శ్రీకృష్ణుడూ అర్జునుడూ కలిసి ఉన్న చోట — దేవుని మార్గదర్శనం, మన నిజాయితీ ప్రయత్నం — అక్కడ విజయం, మంచి తప్పకుండా ఉంటాయి.","hi":"गीता की प्रसिद्ध अंतिम पंक्ति: जहाँ श्रीकृष्ण और अर्जुन साथ हैं — भगवान का मार्गदर्शन और हमारा ईमानदार प्रयास — वहाँ सफलता और भलाई निश्चित है।"},
"vsn_phala_30": {"en":"A beautiful promise: if you keep God in your heart, He takes care of you — He brings what you need and protects what you have.","te":"ఒక అందమైన వాగ్దానం: దేవుణ్ణి హృదయంలో ఉంచుకుంటే ఆయనే మిమ్మల్ని చూసుకుంటాడు — మీకు కావలసింది తెస్తాడు, ఉన్నదాన్ని కాపాడుతాడు.","hi":"एक सुंदर वचन: अगर आप भगवान को हृदय में रखें, तो वे आपकी देखभाल करते हैं — जो चाहिए वह लाते हैं और जो है उसकी रक्षा करते हैं।"},
"vsn_phala_31": {"en":"Another promise from the Gītā: whenever goodness is in danger, God comes again to protect it. We are never left alone.","te":"గీత నుండి మరో వాగ్దానం: మంచితనానికి ప్రమాదం వచ్చినప్పుడల్లా దేవుడు మళ్ళీ వచ్చి కాపాడుతాడు. మనం ఎప్పుడూ ఒంటరిగా విడిచిపెట్టబడం.","hi":"गीता का एक और वचन: जब-जब भलाई ख़तरे में होती है, भगवान उसकी रक्षा के लिए फिर आते हैं। हम कभी अकेले नहीं छोड़े जाते।"},
"vsn_phala_32": {"en":"For anyone who is struggling — sad, weak, scared or ill — even just saying 'Nārāyaṇa' brings relief. The simplest prayer is still a powerful one.","te":"కష్టపడుతున్న ఎవరికైనా — విచారంలో, బలహీనంగా, భయంగా, అనారోగ్యంగా ఉన్నవారికి — ‘నారాయణ’ అని పలికినా ఉపశమనం కలుగుతుంది. అతి సరళమైన ప్రార్థన కూడా శక్తివంతమైనదే.","hi":"जो भी संघर्ष कर रहा है — दुखी, कमज़ोर, डरा हुआ या बीमार — बस 'नारायण' कहने से भी राहत मिलती है। सबसे सरल प्रार्थना भी शक्तिशाली है।"},
"vsn_phala_33": {"en":"We end by offering everything to God — not just the chanting, but every thought, word and action of our day. That turns ordinary life into worship.","te":"చివరగా అన్నిటినీ దేవునికి అర్పిస్తాం — పఠనం మాత్రమే కాదు, రోజంతా మన ప్రతి ఆలోచన, మాట, పని. అలా సాధారణ జీవితమే పూజగా మారుతుంది.","hi":"अंत में हम सब कुछ भगवान को अर्पित करते हैं — केवल पाठ नहीं, बल्कि दिन का हर विचार, शब्द और कर्म। इससे साधारण जीवन ही पूजा बन जाता है।"}
});
